def _parallel_controller_available() -> bool:
    """Expose parallel capability only when a trusted controller is configured."""
    try:
        value=json.loads((ROOT/"harness/controller.json").read_text(encoding="utf-8"))
    except (OSError,UnicodeError,json.JSONDecodeError):
        return False
    command=value.get("command") if isinstance(value,dict) else None
    maximum=value.get("max_workers") if isinstance(value,dict) else None
    executable = False
    if isinstance(command,list) and command and isinstance(command[0],str):
        candidate=Path(command[0])
        executable=(candidate.is_file() and os.access(candidate,os.X_OK)) if candidate.is_absolute() else shutil.which(command[0]) is not None
    return (isinstance(value,dict) and set(value)=={"schema","enabled","command","max_workers"} and value.get("schema")==1 and value.get("enabled") is True and isinstance(command,list) and bool(command) and all(isinstance(part,str) and part for part in command) and executable and isinstance(maximum,int) and not isinstance(maximum,bool) and 1<=maximum<=16)
def _state_domain_from_argv(argv: list[str]) -> tuple[str | None,list[str]]:
    selected=None; remaining=[]; index=0; seen=False
    while index<len(argv):
        value=argv[index]
        if value=="--state-domain":
            if seen: raise ValueError("--state-domain may be specified only once")
            if index+1>=len(argv): raise ValueError("--state-domain requires application or harness")
            selected=argv[index+1]; index+=2; seen=True; continue
        if value.startswith("--state-domain="):
            if seen: raise ValueError("--state-domain may be specified only once")
            selected=value.split("=",1)[1]; index+=1; seen=True; continue
        remaining.append(value); index+=1
    if selected is not None and selected not in {"application","harness"}:
        raise ValueError("--state-domain must be application or harness")
    return selected,remaining


