def _state_path(relative: str) -> Path:
    """Map only fixed state artifacts; shared code/config remains at Git root."""
    if not state_domains.is_owned_path(relative):
        return ROOT / relative
    return ROOT/state_domains.owner(STATE_DOMAIN,relative)


def _domain_path(relative: str, domain: str | None = None) -> str:
    """Return one fixed state artifact's canonical Git path for its owner."""
    return state_domains.owner(STATE_DOMAIN if domain is None else domain,relative)


