    global STATE_DOMAIN,STATE_ROOT,FEATURE_PATH,OUTCOMES_PATH,RECOVERY_PATH,ATTESTATIONS_DIR,REVIEWS_DIR,REGISTRY_PATH,GENERATED_INDEX,GENERATED_RECOVERY_VIEW
