    if domain=="harness" and (not harness_root.is_dir() or harness_root.is_symlink()) and not (allow_completed_recovery and not os.path.lexists(harness_root)):
        raise ValueError("harness state domain is not initialized safely")
    STATE_DOMAIN=domain
    STATE_ROOT=ROOT if domain=="application" else ROOT/".agent-harness"
    FEATURE_PATH=_state_path("feature_list.json")
