def _generated_origin_evidence_error(payloads: dict[str,bytes], operation: str, *, allow_partial_pending: bool = False) -> str | None:
    """Reauthenticate schema-2 source receipts immediately before a passing ref."""
    raw=payloads.get(_domain_path("feature_list.json"))
    if raw is None: return None
    try:
        document=json.loads(raw.decode("utf-8")); session=read_session()
        if not isinstance(session,dict): return "BLOCK_COMMIT_EVIDENCE_ORIGIN_INVALID"
        work_item=session.get("work_item")
        passed=[entry for entry in document.get("features",[]) if isinstance(entry,dict) and entry.get("id")==work_item and entry.get("status")=="passing" and any(isinstance(evidence,dict) and evidence.get("schema") in {2,3} for evidence in entry.get("evidence",[]))]
        if not passed: return None
        if len(passed)!=1 or operation not in {"activate-successor","complete-request"}: return "BLOCK_COMMIT_EVIDENCE_ORIGIN_INVALID"
        item=passed[0]; evidence=item.get("evidence")
        if not durable_evidence_valid(item,evidence,project(),payloads): return "BLOCK_COMMIT_EVIDENCE_SOURCE_CHANGED"
        sources={(entry.get("source_commit"),entry.get("resolution_commit")) for entry in evidence if isinstance(entry,dict)}
        if len(sources)!=1: return "BLOCK_COMMIT_EVIDENCE_ORIGIN_INVALID"
        source,resolution=next(iter(sources)); head=git("rev-parse","HEAD").decode().strip()
        state=session.get("state_handoff")
        if (not isinstance(source,str) or not isinstance(resolution,str) or not isinstance(state,dict)
            or state.get("operation")!=operation or state.get("state")!="pending"):
            return "BLOCK_COMMIT_EVIDENCE_ORIGIN_INVALID"
        parent=state.get("parent_head"); expected=state.get("expected_commit")
        paths=state.get("paths")
        if (not isinstance(parent,str) or not isinstance(expected,str) or resolution!=parent
            or git("rev-list","--parents","-n","1",expected).decode().strip().split()!=[expected,parent]
            or git("rev-parse",expected+"^{tree}").decode().strip()!=state.get("candidate_tree")
            or head not in {parent,expected}):
            return "BLOCK_COMMIT_EVIDENCE_RESOLUTION_CHANGED"
        if not isinstance(paths,list) or paths!=sorted(set(paths)) or set(payloads)!=set(paths): return "BLOCK_STATE_CANDIDATE_CHANGED"
        changed=[entry.decode("utf-8","surrogateescape") for entry in git("diff-tree","--no-commit-id","--name-only","-r","-z","--no-renames",parent,expected).split(b"\0") if entry]
        if changed!=paths or any(_git_file(expected,path)!=payloads[path] for path in paths): return "BLOCK_STATE_CANDIDATE_CHANGED"
        if head==parent:
            if allow_partial_pending:
                if not _pending_state_matches_parent(state): return "BLOCK_STATE_CANDIDATE_CHANGED"
                paths=set(state.get("paths",[]))
                if any(entry["path"] not in paths for entry in status_entries(refresh_index=False)):
                    return "BLOCK_STATE_CANDIDATE_CHANGED"
                if git("--no-optional-locks","diff","--cached","--raw",parent,"--"):
                    return "BLOCK_PREPARED_INDEX_RECOVERY_REQUIRED"
            else:
                if not _pending_state_matches_worktree(state): return "BLOCK_STATE_CANDIDATE_CHANGED"
                try:
                    for path in state.get("paths",[]):
                        if _generated_path_bytes(path,expected_mode=0o644) is None and _pending_live_bytes(path) is not None:
                            return "BLOCK_STATE_CANDIDATE_CHANGED"
                except ValueError:
                    return "BLOCK_STATE_CANDIDATE_CHANGED"
        else:
            try: published_bytes_match=all(_generated_path_bytes(path,expected_mode=0o644)==payloads[path] for path in paths)
            except ValueError: return "BLOCK_STATE_CANDIDATE_CHANGED"
            if not published_bytes_match: return "BLOCK_STATE_CANDIDATE_CHANGED"
            if any(entry["path"] not in paths for entry in status_entries(refresh_index=False)): return "BLOCK_STATE_CANDIDATE_CHANGED"
            if all(git("--no-optional-locks","diff","--cached","--raw",candidate,"--") for candidate in (parent,expected)):
                return "BLOCK_PREPARED_INDEX_RECOVERY_REQUIRED"
        snapshot=_source_snapshot(resolution,domain=STATE_DOMAIN)
        if snapshot is None: return "BLOCK_COMMIT_EVIDENCE_SOURCE_UNAVAILABLE"
        _cfg,source_doc,_paths=snapshot
        source_items=[entry for entry in source_doc.get("features",[]) if isinstance(entry,dict) and entry.get("id")==item.get("id")]
        if len(source_items)!=1: return "BLOCK_COMMIT_EVIDENCE_SOURCE_INVALID"
        reusable=_origin_receipts(source,resolution,source_items[0],allow_generated_state=True)
        if reusable is None: return "BLOCK_COMMIT_EVIDENCE_ORIGIN_MISSING"
        origin,original=reusable
        if len(evidence)!=len(item.get("required_profiles",[])): return "BLOCK_COMMIT_EVIDENCE_SOURCE_CHANGED"
        for entry in evidence:
            receipt=original.get(entry.get("profile")) if isinstance(entry,dict) else None
            expected_schema=2 if origin.get("schema")==1 else 3
            if (entry.get("schema")!=expected_schema or entry.get("source_commit")!=source or entry.get("resolution_commit")!=resolution or receipt is None
                or (expected_schema==3 and (entry.get("state_domain")!=STATE_DOMAIN or entry.get("ledger_path")!=_domain_path("feature_list.json")))
                or entry.get("receipt_digest")!=hashlib.sha256(json.dumps(receipt,sort_keys=True,separators=(",",":")).encode()).hexdigest()
                or any(entry.get(key)!=receipt.get(receipt_key) for key,receipt_key in (("command_digest","command_digest"),("surface_digest","surface_digest"),("profile_digest","profile_digest"),("requirement_digest","requirement_digest"),("verified_at","started_at")))):
                return "BLOCK_COMMIT_EVIDENCE_RECEIPT_CHANGED"
        return None
    except (OSError,KeyError,TypeError,UnicodeError,json.JSONDecodeError,ValueError) as exc:
        return str(exc) if isinstance(exc,ValueError) and str(exc).startswith("BLOCK_COMMIT_EVIDENCE_") else "BLOCK_COMMIT_EVIDENCE_SOURCE_CHANGED"

def _prepare_generated_state_commit(session: dict[str, Any], payloads: dict[str, bytes], message: str, operation: str, next_feature: str | None, *, allow_matching_dirty: bool = False) -> tuple[str | None,str |None]:
    """Persist an exact state handoff before publishing generated repository bytes."""
    paths=sorted(payloads)
    if not paths or any(not safe_relative_path(path,allow_glob=False) or len(payloads[path])>1_000_000 for path in paths): return None,"BLOCK_INVALID_STATE_COMMIT"
    if any(privately_managed_path(path) for path in paths): return None,"BLOCK_PRIVATE_ADOPTION_STATE_COMMIT"
    dirty=status_entries()
    if dirty and (not allow_matching_dirty or any(entry.get("origin_path") is not None or entry.get("path") not in payloads or _pending_live_bytes(entry["path"])!=payloads[entry["path"]] for entry in dirty)):
        return None,"BLOCK_PRISTINE_HANDOFF_REQUIRED"
    index_path=Path(git("rev-parse","--git-path","index").decode().strip()); parent=git("rev-parse","HEAD").decode().strip(); index_name=f"commit-index-{session['receipt_key'][:16]}"; temporary=git_dir()/index_name
    try: temporary.unlink()
    except FileNotFoundError: pass
    git_with_index(str(temporary),"read-tree","HEAD")
    for path in paths:
        blob=git_with_index_input(str(temporary),payloads[path],"hash-object","-w","--stdin").decode().strip()
        git_with_index(str(temporary),"update-index","--add","--cacheinfo",f"100644,{blob},{path}")
    staged=[entry.decode("utf-8","surrogateescape") for entry in git_with_index(str(temporary),"diff","--cached","--name-only","-z").split(b"\0") if entry]
    if staged!=paths: return None,"BLOCK_STATE_SCOPE_CHANGED"
    tree=git_with_index(str(temporary),"write-tree").decode().strip(); expected=git_with_index_input(str(temporary),(message+"\n").encode(),"commit-tree",tree,"-p",parent).decode().strip(); token=index_token(index_path); prepared_index_digest=hashlib.sha256(temporary.read_bytes()).hexdigest()
    pointer_preimage=hashlib.sha256((ROOT/_domain_path(".specify/feature.json")).read_bytes()).hexdigest() if operation=="activate-successor" else None
    pending={"schema":1,"state":"pending","operation":operation,"parent_head":parent,"committed_head":None,"candidate_tree":tree,"expected_commit":expected,"message_digest":hashlib.sha256((message+"\n").encode()).hexdigest(),"index_name":index_name,"index_token":token,"prepared_index_digest":prepared_index_digest,"lock_identity":None,"hook_digest":commit_hook_digest(),"next_feature":next_feature,"paths":paths,"pointer_preimage":pointer_preimage,"review_outcomes_digest":review_outcomes_digest(session.get("review_outcomes",[])) if operation=="resolve-review" else None}
    if operation == "resolve-review":
        pending["evidence_digest"] = evidence_digest(session)
    if operation in {"activate-successor", "complete-request"} and session.get("review_outcomes"):
        pending["review_retirement_digest"] = review_outcomes_digest(session.get("review_outcomes",[]))
        pending["receipt_set_digest"] = evidence_digest(session)
    if operation=="record-content": pending["rotation_key"]=secrets.token_hex(32)
    if session.get("request_ref") is not None:
        _publish_request_binding("request-state-"+expected+".json",_request_state_binding(session,pending))
    session["state_handoff"]=pending; publish_session(session,replace=True)
    if not _pending_state_matches_parent(pending): return None,"BLOCK_STATE_CANDIDATE_CHANGED"
    if operation=="resolve-review":
        # The durable review record is deliberately visible before the gate can
        # disappear.  A failure in the following feature-list publication leaves
        # an exact pending descriptor for recovery, never an unproven clearance.
        publish_paths=[path for path in paths if path.startswith(_domain_path("harness/reviews")+"/")]+([_domain_path("feature_list.json")] if _domain_path("feature_list.json") in paths else [])+([_domain_path(".specify/feature.json")] if _domain_path(".specify/feature.json") in paths else [])
    elif operation=="record-content":
        publish_paths=paths
    else:
        # Attestations explain the activation before its status is published;
        # the ignored SpecKit pointer is deliberately last.
        publish_paths=[path for path in paths if path.startswith(_domain_path("harness/attestations")+"/")]+[path for path in paths if path.startswith(_domain_path("harness/requests")+"/")]+[_domain_path("feature_list.json")]+([_domain_path(".specify/feature.json")] if operation=="activate-successor" else [])
    for path in publish_paths:
        if not _pending_state_path_matches_parent(pending,path): return None,"BLOCK_STATE_CANDIDATE_CHANGED"
        parts=Path(path).parts; directory_fd=open_repo_directory(*parts[:-1],create=True)
        try: _publish_bytes(directory_fd,parts[-1],payloads[path],replace=True,mode=0o644)
        finally: os.close(directory_fd)
    if not _pending_state_matches_worktree(pending): return None,"BLOCK_STATE_CANDIDATE_CHANGED"
    pending["index_token"]=index_token(index_path); session["state_handoff"]=pending; publish_session(session,replace=True)
    unclaimed_session_digest=_session_payload_digest(session)
    reservation=reserve_prepared_index(index_name,pending["index_token"],tree,prepared_index_digest)
    if not reservation: return None,"BLOCK_STATE_INDEX_CHANGED"
    lock,descriptor,identity=reservation
    current,blocked=_claimed_initial_session("state_handoff",unclaimed_session_digest,pending,lock,descriptor,identity)
    if blocked: return None,blocked
    pending=current["state_handoff"]; pending["lock_identity"]=f"{identity[0]}:{identity[1]}"; current["state_handoff"]=pending
    claimed_session_digest=_session_payload_digest(current)
    try: publish_session(current,replace=True)
    except ValueError:
        _cleanup_failed_initial_index_claim("state_handoff",unclaimed_session_digest,claimed_session_digest,pending,lock,descriptor,identity); raise
    session.clear(); session.update(current)
    if not _pending_state_matches_worktree(pending) or not prepared_index_matches_tree(lock,tree,prepared_index_digest) or local_commit_requires_manual_git() or pending["hook_digest"]!=commit_hook_digest():
        _release_exact_initial_claim_for_retry("state_handoff",pending,lock,descriptor,identity,expected_session_digest=claimed_session_digest)
        return None,"BLOCK_STATE_CANDIDATE_CHANGED"
    _before_state_head_publication()
    if any(isinstance(record,dict) and record.get("stage")=="final_authority" for record in session.get("review_outcomes",[])) and session_review_readiness_errors(session):
        _release_exact_initial_claim_for_retry("state_handoff",pending,lock,descriptor,identity,expected_session_digest=claimed_session_digest)
        return None,"BLOCK_FINAL_AUTHORITY_INVENTORY_CHANGED"
    current,blocked=_late_initial_ref_authority("state_handoff",pending,lock,descriptor,identity,claimed_session_digest)
    if blocked: return None,blocked
    # Callers retain this session object across generated transitions (advance
    # and request journaling). Preserve that alias after the exact persisted
    # handoff check so they cannot rotate or publish from stale pending state.
    session.clear(); session.update(current); pending=session["state_handoff"]
    source_error=_generated_origin_evidence_error(payloads,operation)
    if source_error:
        _release_exact_initial_claim_for_retry("state_handoff",pending,lock,descriptor,identity,expected_session_digest=claimed_session_digest)
        return None,source_error
    try: git("update-ref","HEAD",expected,parent)
    except ValueError:
        _release_exact_initial_claim_for_retry("state_handoff",pending,lock,descriptor,identity,expected_session_digest=claimed_session_digest); raise
    if not finalize_prepared_index_reservation(lock,descriptor,identity,tree,prepared_index_digest): return expected,"RECOVERY_REQUIRED"
    pending["state"]="committed"; pending["committed_head"]=expected; session["state_handoff"]=pending; publish_session(session,replace=True)
    return expected,None


def _review_resolution_ready(session: dict[str, Any], item: dict[str, Any], handoff: dict[str, Any]) -> tuple[list[dict[str, Any]] | None,str | None]:
    state=session.get("state_handoff"); source=handoff.get("committed_head")
    if session_review_readiness_errors(session): return None,"BLOCK_UNRESOLVED_MATERIAL_REVIEW"
    if (isinstance(source,str) and isinstance(state,dict) and state.get("operation")=="resolve-review"
            and state.get("state")=="committed" and state.get("committed_head")==git("rev-parse","HEAD").decode().strip()
            and _revalidation_review_resolution_child(source,state["committed_head"],item)):
        return [],None
    gates=item.get("external_gates",[])
    if any(gate!="independent-review" for gate in gates): return None,"BLOCK_UNRESOLVED_EXTERNAL_GATES"
    expected=required_review_stages(item); outcomes=session.get("review_outcomes",[])
    if not expected: return [],None
    if "independent-review" not in gates:
        if _installed_local_state_binding() is not None:
            source=handoff.get("committed_head")
            raw=_local_transition_file_bytes(_domain_path(f"harness/reviews/{source}.json")) if isinstance(source,str) else None
            try: record=_strict_request_json(raw) if raw is not None else None
            except (ValueError,json.JSONDecodeError): record=None
            source_feature=record.get("source_feature") if isinstance(record,dict) else None
            resolved=record.get("resolved_feature") if isinstance(record,dict) else None
            resolved_digest=hashlib.sha256(json.dumps(resolved,sort_keys=True,separators=(",",":")).encode()).hexdigest() if isinstance(resolved,dict) else None
            try: source_tree=git("rev-parse",source+"^{tree}").decode().strip() if isinstance(source,str) else None
            except ValueError: source_tree=None
            current_scope={key:value for key,value in item.items() if key not in {"status","evidence","next_action"}}
            resolved_scope={key:value for key,value in resolved.items() if key not in {"status","evidence","next_action"}} if isinstance(resolved,dict) else None
            recorded_outcomes=record.get("outcomes") if isinstance(record,dict) else None
            if (isinstance(record,dict) and record.get("source_commit")==source and record.get("candidate_tree")==source_tree and record.get("work_item")==item.get("id")
                and isinstance(source_feature,dict) and isinstance(resolved,dict) and record.get("resolved_feature_digest")==resolved_digest and current_scope==resolved_scope
                and record.get("outcomes_digest")==review_outcomes_digest(recorded_outcomes)
                and (recorded_outcomes==outcomes or outcomes==[])
                and not review_outcomes_errors(recorded_outcomes,session,source_feature,source_surface_digest=surface_digest(item))
                and [entry.get("stage") for entry in recorded_outcomes if isinstance(entry,dict)]==expected):
                return [],None
        state=session.get("state_handoff")
        if isinstance(state,dict) and state.get("operation")=="resolve-review" and state.get("state")=="committed" and state.get("committed_head")==git("rev-parse","HEAD").decode().strip():
            source=handoff.get("committed_head")
            artifact=_git_file(state["committed_head"],f"harness/reviews/{source}.json") if isinstance(source,str) else None
            if artifact is not None:
                record=_strict_request_json(artifact)
                source_item=_review_feature_at_source_commit(source,item)
                source_objects=_tree_objects(source) if source_item is not None else None
                source_surface=_surface_digest_at_commit(source_item,source,set(source_objects),domain=STATE_DOMAIN,generation="current",installed_runtime=_installed_local_state_binding() is not None) if source_objects is not None else None
                if source_item is not None and source_surface is not None and record.get("work_item")==item.get("id") and record.get("source_commit")==source and record.get("candidate_tree")==handoff.get("candidate_tree") and record.get("outcomes")==outcomes and not review_outcomes_errors(record.get("outcomes"),session,source_item,source_surface_digest=source_surface) and [entry.get("stage") for entry in outcomes]==expected:
                    return [],None
    if review_outcomes_errors(outcomes,session,item) or [entry.get("stage") for entry in outcomes]!=expected: return None,"BLOCK_REQUIRED_CONTROLLER_REVIEWS"
    for outcome in outcomes:
        if outcome.get("task")!=handoff.get("task") or outcome.get("source_commit")!=handoff.get("committed_head") or outcome.get("candidate_tree")!=handoff.get("candidate_tree") or outcome.get("surface_digest")!=surface_digest(item) or outcome.get("profile_digest")!=profile_digest(item) or outcome.get("requirement_digest")!=requirement_digest(item) or outcome.get("policy_digest")!=review_authority_digest(session["continuation_policy"]) or outcome.get("scope_digest")!=continuation_scope_digest(session): return None,"BLOCK_STALE_CONTROLLER_REVIEW"
    return outcomes,None


def _review_feature_at_source_commit(source_commit: str, current_item: dict[str, Any]) -> dict[str, Any] | None:
    """Load the reviewed feature and allow only the exact gate-clearing edit."""
    if _installed_local_state_binding() is not None:
        try:
            raw=_local_transition_file_bytes(_domain_path(f"harness/reviews/{source_commit}.json"))
            record=_strict_request_json(raw) if raw is not None else None
            source_item=record.get("source_feature") if isinstance(record,dict) else None
            resolved=record.get("resolved_feature") if isinstance(record,dict) else None
            if (not isinstance(source_item,dict) or not isinstance(resolved,dict) or record.get("source_commit")!=source_commit
                or record.get("work_item")!=current_item.get("id") or current_item.get("external_gates")!=[]
                or source_item.get("external_gates") not in ([],["independent-review"])
                or record.get("resolved_feature_digest")!=hashlib.sha256(json.dumps(resolved,sort_keys=True,separators=(",",":")).encode()).hexdigest()): return None
            return source_item if {key:value for key,value in source_item.items() if key!="external_gates"}=={key:value for key,value in resolved.items() if key!="external_gates"} else None
        except (OSError,ValueError,KeyError,TypeError): return None
    raw=_git_file(source_commit,"feature_list.json")
    if raw is None: return None
    try:
        document=_strict_request_json(raw)
        matches=[entry for entry in document.get("features",[]) if isinstance(entry,dict) and entry.get("id")==current_item.get("id")]
        if len(matches)!=1: return None
        source_item=matches[0]
        gates=source_item.get("external_gates")
        if current_item.get("external_gates")!=[] or gates not in ([],["independent-review"]): return None
        source_scope={key:value for key,value in source_item.items() if key!="external_gates"}
        current_scope={key:value for key,value in current_item.items() if key!="external_gates"}
        return source_item if source_scope==current_scope else None
    except (KeyError,TypeError,ValueError):
        return None


def _local_origin_receipts(session: dict[str,Any], item: dict[str,Any]) -> tuple[dict[str,Any],dict[str,dict[str,Any]]] | None:
    """Reuse exact signed source receipts across an authenticated local review edit."""
    if _installed_local_state_binding() is None or item.get("external_gates")!=[]:
        return None
    handoff=session.get("commit_handoff")
    if not isinstance(handoff,dict) or handoff.get("state")!="committed": return None
    source=handoff.get("committed_head")
    if not isinstance(source,str) or git("rev-parse","HEAD").decode().strip()!=source or status_entries(refresh_index=False): return None
    source_item=_review_feature_at_source_commit(source,item)
    if source_item is None or source_item.get("external_gates") not in ([],["independent-review"]): return None
    outcomes,blocked=_review_resolution_ready(session,item,handoff)
    if blocked or outcomes: return None
    review_path=_domain_path(f"harness/reviews/{source}.json")
    try:
        review_raw=_local_transition_file_bytes(review_path)
        review=_strict_request_json(review_raw) if review_raw is not None else None
    except (OSError,UnicodeError,ValueError,json.JSONDecodeError): return None
    journal=_local_review_origin_record(source,review_raw,allow_current=True) if review_raw is not None else None
    if journal is None: return None
    definitions=project()["profiles"]
    if (not isinstance(review,dict) or review.get("source_feature")!=source_item
        or review.get("profile_definitions")!={name:definitions[name] for name in sorted(item["required_profiles"])}): return None
    if git("rev-parse","HEAD^{tree}").decode().strip()!=handoff.get("candidate_tree"): return None
    _require_owner_baseline(session)
    source_session={**session,"base_head":handoff.get("parent_head"),"receipt_key":journal["receipt_key"],"receipt_namespace":f"receipts-{journal['receipt_key'][:16]}"}
    expected_binding=_verification_source_binding(source_session,source_item)
    expected_surface=surface_digest(source_item)
    expected_profile=profile_digest(source_item)
    expected_requirement=requirement_digest(source_item)
    _identity,retained=receipt_namespace_snapshot(journal["receipt_key"],allow_stale_bindings=True,session=source_session)
    selected={}
    for profile in source_item["required_profiles"]:
        matches=[value for _name,(_token,name,value) in sorted(retained.items(),reverse=True) if name==profile and value.get("exit_status")==0 and value.get("candidate_binding")==expected_binding]
        if not matches: return None
        receipt=matches[0]; definition=definitions.get(profile)
        expected_command=hashlib.sha256(json.dumps(definition["commands"],separators=(",",":")).encode()).hexdigest() if isinstance(definition,dict) else None
        if (receipt.get("work_item")!=item["id"] or receipt.get("command_digest")!=expected_command
            or receipt.get("surface_digest")!=expected_surface or receipt.get("profile_digest")!=expected_profile
            or receipt.get("requirement_digest")!=expected_requirement): return None
        selected[profile]=receipt
    return {"source_commit":source,"receipt_key":journal["receipt_key"]},selected


def _required_review_resolution_error(session: dict[str, Any], item: dict[str, Any]) -> str | None:
    """Require every configured review stage and its durable resolution before readiness."""
    if not required_review_stages(item): return None
    handoff=session.get("commit_handoff")
    if not isinstance(handoff,dict) or handoff.get("state")!="committed":
        return "BLOCK_REQUIRED_CONTROLLER_REVIEWS"
    outcomes,blocked=_review_resolution_ready(session,item,handoff)
    if blocked: return blocked
    if outcomes: return "BLOCK_REQUIRED_CONTROLLER_REVIEWS"
    return None


def _review_resolution_payloads(item: dict[str, Any], handoff: dict[str, Any], outcomes: list[dict[str, Any]], session: dict[str,Any] | None = None) -> dict[str, bytes]:
    document=feature_document(); target=next(entry for entry in document["features"] if entry.get("id")==item["id"])
    local_source_feature=json.loads(json.dumps(target)) if _installed_local_state_binding() is not None else None
    record={"schema":1,"work_item":item["id"],"source_commit":handoff["committed_head"],"candidate_tree":handoff["candidate_tree"],"outcomes":outcomes,"note":"Typed controller assertions are durable stage records, not identity proof or publication authority."}
    if "independent-review" in target.get("external_gates",[]):
        source_feature=json.loads(json.dumps(target))
        target["external_gates"]=[gate for gate in target["external_gates"] if gate!="independent-review"]
    if _installed_local_state_binding() is not None:
        definitions=project()["profiles"]
        record["profile_definitions"]={name:definitions[name] for name in sorted(target["required_profiles"])}
        record["source_feature"]=local_source_feature
        record["resolved_feature"]=target
        record["authority_snapshot"]=_local_review_authority_snapshot()
        record["outcomes_digest"]=review_outcomes_digest(outcomes)
        record["resolved_feature_digest"]=hashlib.sha256(json.dumps(target,sort_keys=True,separators=(",",":")).encode()).hexdigest()
    payloads={state_domains.owner(STATE_DOMAIN,f"harness/reviews/{handoff['committed_head']}.json"):(json.dumps(record,indent=2)+"\n").encode()}
    clean_record=_clean_revalidation_record(session,item) if isinstance(session,dict) else None
    if "independent-review" in item.get("external_gates",[]) or clean_record is not None:
        payloads[state_domains.owner(STATE_DOMAIN,"feature_list.json")]=(json.dumps(document,indent=2)+"\n").encode()
    if clean_record is not None:
        pointer_path=state_domains.owner(STATE_DOMAIN,".specify/feature.json")
        pointer=(json.dumps(clean_record[1]["candidate_pointer"],indent=2)+"\n").encode()
        if _git_file(handoff["committed_head"],pointer_path)!=pointer: payloads[pointer_path]=pointer
    return payloads


def _publish_review_resolution(item: dict[str, Any], handoff: dict[str, Any], outcomes: list[dict[str, Any]]) -> None:
    for path,payload in _review_resolution_payloads(item,handoff,outcomes).items():
        if path==state_domains.owner(STATE_DOMAIN,"feature_list.json"): _publish_repository_file(FEATURE_PATH,payload); continue
        parts=Path(path).parts; directory_fd=open_repo_directory(*parts[:-1],create=True)
        try: _publish_bytes(directory_fd,parts[-1],payload,replace=True,mode=0o644)
        finally: os.close(directory_fd)


def _commit_evidence_name(commit: str) -> str:
    if not re.fullmatch(r"[0-9a-f]{40}",commit): raise ValueError("invalid evidence source commit")
    return f"commit-evidence-{commit}.json"


def _continuation_evidence_scope(session: dict[str,Any]) -> dict[str,Any]:
    keys=("work_item","execution_mode","feature_limit","completed_features","follow_on","task_directory","task_ids","builder_binding_ref","builder_model_digest","continuation_policy","source_policy_digest","request_ref")
    value={key:session.get(key) for key in keys}
    if session.get("schema") in {13,14}: value.update(state_domain=session.get("state_domain"),ledger_path=session.get("ledger_path"))
    if session.get("adopted_candidate_digest") is not None: value["adopted_candidate_digest"]=session["adopted_candidate_digest"]
    return value


def _commit_evidence_origin(session: dict[str,Any], item: dict[str,Any], commit: str, tree: str, parent: str) -> dict[str,Any] | None:
    """Bind the exact current signed receipt set to a prepared content commit."""
    _require_owner_baseline(session)
    if _current_evidence_errors(session,item): raise ValueError("BLOCK_COMMIT_EVIDENCE_NOT_CURRENT")
    identity,retained=receipt_namespace_snapshot(session.get("receipt_key",""),allow_stale_bindings=True,session=session)
    if identity is None: raise ValueError("BLOCK_COMMIT_EVIDENCE_NAMESPACE_MISSING")
    source_objects=_tree_objects(commit)
    if source_objects is None: raise ValueError("BLOCK_COMMIT_EVIDENCE_SOURCE_UNAVAILABLE")
    revalidation_binding=_clean_revalidation_origin_binding(session,item)
    source_surface=(surface_digest(item) if revalidation_binding is not None else
        _surface_digest_at_commit(item,commit,set(source_objects),source_objects,domain=STATE_DOMAIN,generation="current",installed_runtime=_installed_local_state_binding() is not None))
    receipts=[]
    for profile in item["required_profiles"]:
        matches=[(name,value) for name,(_token,candidate,value) in retained.items() if candidate==profile and value.get("exit_status")==0]
        if not matches: raise ValueError(f"BLOCK_COMMIT_EVIDENCE_MISSING:{profile}")
        name,value=sorted(matches,key=lambda pair:pair[0])[-1]
        if value.get("work_item")!=item["id"] or value.get("profile_digest")!=profile_digest(item) or value.get("requirement_digest")!=requirement_digest(item):
            raise ValueError(f"BLOCK_COMMIT_EVIDENCE_STALE:{profile}")
        if value.get("surface_digest")!=source_surface:
            # A preserved owner baseline may participate in the working
            # surface while remaining outside the guarded commit. The commit
            # remains valid, but those receipts cannot bridge to its tree.
            return None
        token=retained[name][0]
        receipts.append({"profile":profile,"filename":name,"receipt_digest":token[7]})
    namespace_digest=hashlib.sha256(json.dumps({name:token[7] for name,(token,_profile,_value) in sorted(retained.items())},sort_keys=True,separators=(",",":")).encode()).hexdigest()
    owner_directory=open_admin_directory("repository-agent-session")
    try: owner_bytes=_read_regular_nofollow(owner_directory,_owner_baseline_name(session),"owner baseline authority",expected_mode=0o600)
    finally: os.close(owner_directory)
    owner_binding=json.loads(owner_bytes.decode("utf-8"))
    origin={
        "schema":2,"state_domain":STATE_DOMAIN,"ledger_path":state_domains.owner(STATE_DOMAIN,"feature_list.json"),"source_commit":commit,"source_tree":tree,"parent_commit":parent,
        "work_item":item["id"],"started_at":session["started_at"],"receipt_key":session["receipt_key"],
        "receipt_namespace":receipt_namespace(session),"namespace_identity":list(identity),
        "namespace_digest":namespace_digest,"receipts":receipts,
        "owner_baseline_name":_owner_baseline_name(session),
        "owner_baseline_digest":hashlib.sha256(owner_bytes).hexdigest(),"owner_baseline_binding":owner_binding,
        "requirements_digest":requirement_digest(item),"surface_digest":source_surface,
        "profile_digest":profile_digest(item),"scope_digest":hashlib.sha256(json.dumps(_continuation_evidence_scope(session),sort_keys=True,separators=(",",":")).encode()).hexdigest(),
        "policy_digest":execution_policy_digest(),
    }
    if revalidation_binding is not None:
        origin.update(schema=3,revalidation_journal=revalidation_binding[0],revalidation_digest=revalidation_binding[1])
    return origin


def _publish_commit_evidence_origin(session: dict[str,Any], item: dict[str,Any], commit: str, tree: str, parent: str) -> None:
    """Create the private origin before HEAD can publish the prepared commit."""
    origin=_commit_evidence_origin(session,item,commit,tree,parent)
    if origin is None: return
    payload=(json.dumps(origin,sort_keys=True,separators=(",",":"))+"\n").encode()
    directory_fd=open_admin_directory("repository-agent-session")
    try:
        try: _publish_bytes(directory_fd,_commit_evidence_name(commit),payload,mode=0o600)
        except ValueError:
            retained=_read_regular_nofollow(directory_fd,_commit_evidence_name(commit),"commit evidence origin",expected_mode=0o600)
            if retained!=payload: raise ValueError("BLOCK_COMMIT_EVIDENCE_ORIGIN_CHANGED")
    finally: os.close(directory_fd)


def _review_resolution_child_uncached(source: str, resolution: str, feature_id: str, *, domain: str = "application", generation: str = "legacy") -> bool:
    """Accept only the immutable generated review-artifact child proof."""
    try:
        parents=git("rev-list","--parents","-n","1",resolution).decode().strip().split()
        if parents!=[resolution,source]: return False
        source_objects=_tree_objects(source); result_objects=_tree_objects(resolution)
        if source_objects is None or result_objects is None: return False
        artifact=state_domains.owner(domain,f"harness/reviews/{source}.json")
        raw=git("diff-tree","--no-commit-id","--raw","-r","-z",source,resolution)
        fields=raw.split(b"\0"); changed=set(); index=0
        while index<len(fields) and fields[index]:
            metadata=fields[index].split()
            if len(metadata)!=5 or not metadata[0].startswith(b":"): return False
            path=fields[index+1].decode("utf-8"); changed.add(path)
            if metadata[1]!=b"100644": return False
            index+=2
        if not fields or index<len(fields) and fields[index]: return False
        ledger_path=state_domains.owner(domain,"feature_list.json")
        pointer_path=state_domains.owner(domain,".specify/feature.json")
        if changed not in ({ledger_path,artifact},{ledger_path,pointer_path,artifact},{artifact}): return False
        source_snapshot=_source_snapshot(source,source_objects,domain=domain); result_snapshot=_source_snapshot(resolution,result_objects,domain=domain)
        if source_snapshot is None or result_snapshot is None: return False
        source_cfg,source_doc,_=source_snapshot; _result_cfg,result_doc,_=result_snapshot
        before=[entry for entry in source_doc.get("features",[]) if isinstance(entry,dict) and entry.get("id")==feature_id]
        after=[entry for entry in result_doc.get("features",[]) if isinstance(entry,dict) and entry.get("id")==feature_id]
        if len(before)!=1 or len(after)!=1: return False
        clean_revalidation=False
        if changed=={artifact}:
            if before[0].get("external_gates") or after[0]!=before[0]: return False
        elif "independent-review" not in before[0].get("external_gates",[]):
            source_parents=git("rev-list","--parents","-n","1",source).decode().strip().split()
            if (before[0].get("status")!="passing" or after[0].get("status")!="in_progress" or after[0].get("evidence")!=[]
                    or len(source_parents)!=2 or git("rev-parse",source+"^{tree}").decode().strip()!=git("rev-parse",source_parents[1]+"^{tree}").decode().strip()):
                return False
            clean_revalidation=True
        elif pointer_path in changed:
            return False
        normalized=json.loads(json.dumps(result_doc)); normalized_entry=next(entry for entry in normalized["features"] if entry.get("id")==feature_id)
        if clean_revalidation:
            for key in ("status","evidence","next_action"): normalized_entry[key]=before[0][key]
        else:
            normalized_entry["external_gates"]=before[0]["external_gates"]
        if normalized!=source_doc or (ledger_path in changed and not clean_revalidation and after[0].get("external_gates")!=[gate for gate in before[0]["external_gates"] if gate!="independent-review"]): return False
        review_bytes=_git_file(resolution,artifact,domain=domain)
        if not isinstance(review_bytes,bytes): return False
        review=json.loads(review_bytes.decode("utf-8")); outcomes=review.get("outcomes") if isinstance(review,dict) else None
        source_item=next(entry for entry in source_doc.get("features",[]) if isinstance(entry,dict) and entry.get("id")==feature_id)
        expected_stages=_required_review_stages_at_commit(source,source_item,source_cfg)
        if not isinstance(outcomes,list) or len(outcomes)!=len(expected_stages) or any(not isinstance(entry,dict) for entry in outcomes) or [entry.get("stage") for entry in outcomes]!=expected_stages: return False
        for outcome in outcomes:
            if not isinstance(outcome,dict) or outcome.get("source_commit")!=source or outcome.get("candidate_tree")!=git("rev-parse",source+"^{tree}").decode().strip(): return False
            quality=outcome.get("quality_assessment")
            if outcome.get("stage")=="code_reviewer":
                if not isinstance(quality,dict) or review_quality_errors(quality) or quality.get("outcome")=="blocked": return False
            elif outcome.get("stage")=="final_authority":
                quality_keys={"schema","decision","inventory","inventory_digest","inventory_binding_ref","evidence_digest","selection","findings"}
                findings=quality.get("findings") if isinstance(quality,dict) else None
                if (not isinstance(quality,dict) or set(quality)!=quality_keys or quality.get("schema")!=1 or quality.get("decision") not in {"approval","advisory"} or not isinstance(findings,list)
                    or any(not isinstance(quality.get(key),str) or not re.fullmatch(r"[0-9a-f]{64}",quality[key]) for key in ("inventory_digest","inventory_binding_ref","evidence_digest"))
                    or model_inventory_errors(quality.get("inventory")) or quality.get("inventory_digest")!=inventory_digest(quality["inventory"])
                    or any(not isinstance(finding,dict) or set(finding)!={"severity","summary","evidence"} or finding.get("severity") not in {"material","advisory"} or not safe_public_text(finding.get("summary"),limit=2000) or not safe_public_text(finding.get("evidence"),limit=2000) for finding in findings)
                    or any(finding["severity"]=="material" for finding in findings)
                    or quality.get("decision")!= ("advisory" if findings else "approval")):
                    return False
            elif quality is not None: return False
        return (isinstance(review,dict) and review.get("schema")==1 and review.get("work_item")==feature_id and review.get("source_commit")==source and review.get("candidate_tree")==git("rev-parse",source+"^{tree}").decode().strip() and review.get("note")=="Typed controller assertions are durable stage records, not identity proof or publication authority.")
    except (KeyError,TypeError,UnicodeError,ValueError,json.JSONDecodeError):
        return False


_REVIEW_RESOLUTION_PROOFS: OrderedDict[tuple[Any,...],bool]=OrderedDict()


def _review_resolution_child(source: str, resolution: str, feature_id: str, *, domain: str = "application", generation: str = "legacy") -> bool:
    """Memoize only successful immutable proofs within one repository identity."""
    try:
        root=ROOT.resolve(strict=True); metadata=root.stat()
        feature_path=str(FEATURE_PATH.resolve(strict=False))
    except (OSError,RuntimeError):
        return _review_resolution_child_uncached(source,resolution,feature_id,domain=domain,generation=generation)
    try:
        if git("for-each-ref","--format=%(refname)","refs/replace").strip():
            return _review_resolution_child_uncached(source,resolution,feature_id,domain=domain,generation=generation)
    except (OSError,ValueError,subprocess.SubprocessError):
        return _review_resolution_child_uncached(source,resolution,feature_id,domain=domain,generation=generation)
    key=(str(root),metadata.st_dev,metadata.st_ino,domain,generation,feature_path,source,resolution,feature_id)
    if key in _REVIEW_RESOLUTION_PROOFS:
        _REVIEW_RESOLUTION_PROOFS.move_to_end(key)
        return True
    proven=_review_resolution_child_uncached(source,resolution,feature_id,domain=domain,generation=generation)
    if proven:
        _REVIEW_RESOLUTION_PROOFS[key]=True
        _REVIEW_RESOLUTION_PROOFS.move_to_end(key)
        if len(_REVIEW_RESOLUTION_PROOFS)>512: _REVIEW_RESOLUTION_PROOFS.popitem(last=False)
    return proven


def _revalidation_review_resolution_child(source: str, resolution: str, item: dict[str,Any], origin: dict[str,Any] | None = None) -> bool:
    """Prove the exact no-op revalidation commit and its review-state child."""
    try:
        session=read_session(); handoff=session.get("commit_handoff") if isinstance(session,dict) else None
        state=session.get("state_handoff") if isinstance(session,dict) else None
        ledger_path=_domain_path("feature_list.json"); pointer_path=_domain_path(".specify/feature.json"); artifact=_domain_path(f"harness/reviews/{source}.json")
        review_path_sets=(sorted([ledger_path,artifact]),sorted([ledger_path,pointer_path,artifact]))
        if (not isinstance(session,dict) or session.get("work_item")!=item.get("id")
                or not isinstance(handoff,dict) or handoff.get("state")!="committed"
                or handoff.get("committed_head")!=source or commit_handoff_errors(handoff,session)
                or not isinstance(state,dict) or state_handoff_errors(state,session)):
            return False
        head=git("rev-parse","HEAD").decode().strip()
        resolving=(state.get("operation")=="resolve-review" and state.get("state")=="committed"
            and state.get("parent_head")==source and state.get("committed_head")==resolution
            and state.get("expected_commit")==resolution and state.get("paths") in review_path_sets
            and _review_state_binding_matches(session,state) and head==resolution
            and git("rev-parse",resolution+"^{tree}").decode().strip()==state.get("candidate_tree"))
        retiring=(state.get("operation") in {"activate-successor","complete-request"}
            and state.get("parent_head")==resolution and head in {resolution,state.get("expected_commit")}
            and _review_retirement_state_matches(session,state))
        if not resolving and not retiring: return False
        changed=[entry.decode("utf-8","surrogateescape") for entry in git("diff-tree","--no-commit-id","--name-only","-r","-z","--no-renames",source,resolution).split(b"\0") if entry]
        if changed not in review_path_sets: return False
        outcomes=session.get("review_outcomes",[]); expected=required_review_stages(item)
        retained_surface=origin.get("surface_digest") if isinstance(origin,dict) and origin.get("schema")==3 else None
        if retained_surface is None and (resolving or retiring):
            retained_surfaces={entry.get("surface_digest") for entry in outcomes if isinstance(entry,dict)}
            if len(retained_surfaces)==1 and isinstance(next(iter(retained_surfaces)),str): retained_surface=next(iter(retained_surfaces))
        if review_outcomes_errors(outcomes,session,item,source_surface_digest=retained_surface) or [entry.get("stage") for entry in outcomes]!=expected:
            return False
        record=_strict_request_json(_git_file(resolution,artifact))
        if (record.get("schema")!=1 or record.get("work_item")!=item.get("id") or record.get("source_commit")!=source
                or record.get("candidate_tree")!=git("rev-parse",source+"^{tree}").decode().strip()
                or record.get("outcomes")!=outcomes
                or record.get("note")!="Typed controller assertions are durable stage records, not identity proof or publication authority."):
            return False
        if isinstance(origin,dict) and origin.get("schema")==3:
            name=origin.get("revalidation_journal"); expected_digest=origin.get("revalidation_digest")
            if not isinstance(name,str) or not re.fullmatch(re.escape(item["id"])+r"-[0-9a-f]{16}\.json",name): return False
            journal=_lifecycle_private_read("revalidations",name)
            if not isinstance(journal,dict) or journal.get("digest")!=expected_digest: return False
            body={key:value for key,value in journal.items() if key!="digest"}
            if hashlib.sha256(json.dumps(body,sort_keys=True,separators=(",",":")).encode()).hexdigest()!=expected_digest: return False
        elif resolving or retiring:
            resolution_document=feature_document() if resolving else _strict_request_json(_git_file(resolution,ledger_path))
            directory=git_dir()/"lifecycle"/STATE_DOMAIN/"revalidations"
            names=sorted(name for name in os.listdir(directory) if name.startswith(item["id"]+"-"))
            journals=[]
            for name in names:
                if not re.fullmatch(re.escape(item["id"])+r"-[0-9a-f]{16}\.json",name): continue
                candidate=_lifecycle_private_read("revalidations",name)
                if not isinstance(candidate,dict) or candidate.get("head")!=handoff.get("parent_head") or candidate.get("tree")!=handoff.get("candidate_tree"): continue
                recovered=_recover_revalidation(candidate,name,allow_resolution_source=source)
                if recovered.get("candidate_document")==resolution_document: journals.append(recovered)
            if len(journals)!=1: return False
            journal=journals[0]
        else:
            return False
        if (journal.get("state")!="published" or journal.get("feature_id")!=item.get("id")
                or journal.get("head")!=handoff.get("parent_head") or journal.get("tree")!=handoff.get("candidate_tree")
                or git("rev-list","--parents","-n","1",source).decode().strip().split()!=[source,journal["head"]]
                or git("rev-parse",source+"^{tree}").decode().strip()!=journal["tree"]
                or git("rev-list","--parents","-n","1",resolution).decode().strip().split()!=[resolution,source]):
            return False
        ledger=(json.dumps(journal["candidate_document"],indent=2)+"\n").encode()
        candidates=[entry for entry in journal["candidate_document"].get("features",[]) if isinstance(entry,dict) and entry.get("id")==item.get("id")]
        return len(candidates)==1 and candidates[0]==item and _git_file(resolution,ledger_path)==ledger
    except (OSError,KeyError,TypeError,UnicodeError,ValueError,json.JSONDecodeError):
        return False


def _origin_receipts(source: str, resolution: str, item: dict[str,Any], *, allow_generated_state: bool = False) -> tuple[dict[str,Any],dict[str,dict[str,Any]]] | None:
    """Return authenticated original receipts for the exact allowed child R."""
    directory_fd=None; descriptor=None
    try:
        directory_fd=open_admin_directory("repository-agent-session")
        descriptor=os.open(_commit_evidence_name(source),os.O_RDONLY|getattr(os,"O_NOFOLLOW",0)|getattr(os,"O_NONBLOCK",0),dir_fd=directory_fd)
        metadata=os.fstat(descriptor)
        if not stat.S_ISREG(metadata.st_mode) or stat.S_IMODE(metadata.st_mode)!=0o600: raise ValueError("BLOCK_COMMIT_EVIDENCE_ORIGIN_INVALID")
        payload=b""
        while True:
            chunk=os.read(descriptor,65536)
            if not chunk: break
            payload+=chunk
            if len(payload)>1_000_000: raise ValueError("BLOCK_COMMIT_EVIDENCE_ORIGIN_INVALID")
        origin=json.loads(payload.decode("utf-8"))
    except FileNotFoundError:
        return None
    except (OSError,UnicodeError,json.JSONDecodeError) as exc:
        raise ValueError("BLOCK_COMMIT_EVIDENCE_ORIGIN_INVALID") from exc
    finally:
        if descriptor is not None: os.close(descriptor)
        if directory_fd is not None: os.close(directory_fd)
    required={"schema","source_commit","source_tree","parent_commit","work_item","started_at","receipt_key","receipt_namespace","namespace_identity","namespace_digest","receipts","owner_baseline_digest","owner_baseline_binding","owner_baseline_name","requirements_digest","surface_digest","profile_digest","scope_digest","policy_digest"}
    required_v2=required|{"state_domain","ledger_path"}
    required_v3=required_v2|{"revalidation_journal","revalidation_digest"}
    valid_v1=isinstance(origin,dict) and set(origin)==required and origin.get("schema")==1 and STATE_DOMAIN=="application"
    valid_v2=isinstance(origin,dict) and set(origin)==required_v2 and origin.get("schema")==2 and origin.get("state_domain")==STATE_DOMAIN and origin.get("ledger_path")==state_domains.owner(STATE_DOMAIN,"feature_list.json")
    valid_v3=(isinstance(origin,dict) and set(origin)==required_v3 and origin.get("schema")==3
        and origin.get("state_domain")==STATE_DOMAIN and origin.get("ledger_path")==state_domains.owner(STATE_DOMAIN,"feature_list.json")
        and isinstance(origin.get("revalidation_journal"),str) and re.fullmatch(r"[A-Z][A-Z0-9]*-[0-9]{3}-[0-9a-f]{16}\.json",origin["revalidation_journal"])
        and isinstance(origin.get("revalidation_digest"),str) and re.fullmatch(r"[0-9a-f]{64}",origin["revalidation_digest"]))
    if not isinstance(origin,dict) or type(origin.get("schema")) is not int or not (valid_v1 or valid_v2 or valid_v3): raise ValueError("BLOCK_COMMIT_EVIDENCE_ORIGIN_INVALID")
    if origin.get("source_commit")!=source or origin.get("work_item")!=item["id"] or origin.get("source_tree")!=git("rev-parse",source+"^{tree}").decode().strip() or origin.get("receipt_namespace")!=f"receipts-{origin.get('receipt_key','')[:16]}" or not re.fullmatch(r"[0-9a-f]{64}",origin.get("receipt_key","")): raise ValueError("BLOCK_COMMIT_EVIDENCE_ORIGIN_INVALID")
    origin_domain=origin.get("state_domain","application")
    source_generation="current" if origin.get("schema") in {2,3} else "legacy"
    revalidation_resolution=origin.get("schema")==3 and _revalidation_review_resolution_child(source,resolution,item,origin)
    ordinary_resolution=not revalidation_resolution and _review_resolution_child(source,resolution,item["id"],domain=origin_domain,generation=source_generation)
    if not ordinary_resolution and not revalidation_resolution: raise ValueError("BLOCK_COMMIT_EVIDENCE_RESOLUTION_CHANGED")
    source_objects=_tree_objects(source); source_snapshot=_source_snapshot(source,source_objects,domain=origin_domain)
    if source_snapshot is None: raise ValueError("BLOCK_COMMIT_EVIDENCE_SOURCE_UNAVAILABLE")
    source_cfg,source_doc,source_paths=source_snapshot
    source_items=[entry for entry in source_doc.get("features",[]) if isinstance(entry,dict) and entry.get("id")==item["id"]]
    if len(source_items)!=1: raise ValueError("BLOCK_COMMIT_EVIDENCE_SOURCE_INVALID")
    source_item=source_items[0]
    acceptance={key:value for key,value in item.items() if key not in {"status","evidence","next_action"}}
    source_acceptance={key:value for key,value in source_item.items() if key not in {"status","evidence","next_action"}}
    acceptance["external_gates"]=source_item.get("external_gates",[])
    source_profile_digest=hashlib.sha256(json.dumps({name:source_cfg["profiles"][name] for name in sorted(source_item["required_profiles"])},sort_keys=True,separators=(",",":")).encode()).hexdigest()
    source_surface=(_surface_digest_at_commit(item,resolution,set(_tree_objects(resolution) or {}),domain=origin_domain,generation=source_generation)
        if revalidation_resolution else _surface_digest_at_commit(source_item,source,set(source_objects),source_objects,domain=origin_domain,generation=source_generation))
    if acceptance!=source_acceptance or origin.get("requirements_digest")!=requirement_digest(source_item) or origin.get("profile_digest")!=source_profile_digest or origin.get("surface_digest")!=source_surface: raise ValueError("BLOCK_COMMIT_EVIDENCE_SOURCE_CHANGED")
    resolution_objects=_tree_objects(resolution)
    if resolution_objects is None or profile_digest(item)!=origin.get("profile_digest"): raise ValueError("BLOCK_COMMIT_EVIDENCE_LIVE_SURFACE_CHANGED")
    if not allow_generated_state and (surface_digest(item)!=_surface_digest_at_commit(item,resolution,set(resolution_objects),resolution_objects,domain=origin_domain,generation=source_generation) or status_entries()): raise ValueError("BLOCK_COMMIT_EVIDENCE_LIVE_SOURCE_CHANGED")
    scope_session=read_session()
    source_adoption=origin.get("owner_baseline_binding",{}).get("adopted_candidate_digest") if isinstance(origin.get("owner_baseline_binding"),dict) else None
    if scope_session.get("adopted_candidate_digest") is None and isinstance(source_adoption,str) and re.fullmatch(r"[0-9a-f]{64}",source_adoption):
        # The one-shot permission is retired in the successor session after
        # commit, while the authenticated source baseline remains in the
        # immutable evidence origin. Reattach only that provenance field when
        # checking the original commit's evidence scope.
        scope_session={**scope_session,"adopted_candidate_digest":source_adoption}
    if origin.get("policy_digest")!=execution_policy_digest() or origin.get("scope_digest")!=hashlib.sha256(json.dumps(_continuation_evidence_scope(scope_session),sort_keys=True,separators=(",",":")).encode()).hexdigest(): raise ValueError("BLOCK_COMMIT_EVIDENCE_SCOPE_CHANGED")
    source_session={"started_at":origin["started_at"],"receipt_key":origin["receipt_key"],"receipt_namespace":origin["receipt_namespace"]}
    owner_directory=open_admin_directory("repository-agent-session")
    try:
        owner_bytes=_read_regular_nofollow(owner_directory,origin["owner_baseline_name"],"owner baseline authority",expected_mode=0o600)
    finally: os.close(owner_directory)
    if hashlib.sha256(owner_bytes).hexdigest()!=origin.get("owner_baseline_digest") or json.loads(owner_bytes.decode("utf-8"))!=origin.get("owner_baseline_binding"): raise ValueError("BLOCK_COMMIT_EVIDENCE_BASELINE_CHANGED")
    _require_owner_baseline(read_session())
    identity,retained=receipt_namespace_snapshot(origin["receipt_key"],allow_stale_bindings=True,session=source_session)
    if identity is None or list(identity)!=origin.get("namespace_identity"): raise ValueError("BLOCK_COMMIT_EVIDENCE_NAMESPACE_CHANGED")
    namespace_digest=hashlib.sha256(json.dumps({name:token[7] for name,(token,_profile,_value) in sorted(retained.items())},sort_keys=True,separators=(",",":")).encode()).hexdigest()
    if namespace_digest!=origin.get("namespace_digest"): raise ValueError("BLOCK_COMMIT_EVIDENCE_RECEIPT_SET_CHANGED")
    declared=origin.get("receipts")
    if not isinstance(declared,list) or [entry.get("profile") for entry in declared if isinstance(entry,dict)]!=source_item["required_profiles"]: raise ValueError("BLOCK_COMMIT_EVIDENCE_ORIGIN_INVALID")
    selected={}
    for record in declared:
        name=record.get("filename"); profile=record.get("profile"); found=retained.get(name)
        if not isinstance(name,str) or not isinstance(profile,str) or found is None or found[1]!=profile or found[0][7]!=record.get("receipt_digest") or found[2].get("exit_status")!=0: raise ValueError("BLOCK_COMMIT_EVIDENCE_RECEIPT_CHANGED")
        receipt=found[2]; definition=source_cfg["profiles"].get(profile)
        expected_command=hashlib.sha256(json.dumps(definition["commands"],separators=(",",":")).encode()).hexdigest() if isinstance(definition,dict) else None
        if receipt.get("work_item")!=item["id"] or receipt.get("command_digest")!=expected_command or receipt.get("surface_digest")!=origin["surface_digest"] or receipt.get("profile_digest")!=origin["profile_digest"] or receipt.get("requirement_digest")!=origin["requirements_digest"]:
            raise ValueError("BLOCK_COMMIT_EVIDENCE_RECEIPT_BINDING_CHANGED")
        selected[profile]=found[2]
    return origin,selected


def commit(args: list[str]) -> int:
    if len(args)!=4 or args[0]!="--task" or args[2]!="--message" or not re.fullmatch(r"T[0-9]{3}",args[1]) or not safe_public_text(args[3],limit=200):
        print("Usage: bin/agent-session commit --task Txxx --message TEXT",file=sys.stderr); return 64
    try:
        with admin_transaction():
            with local_commit_lock():
                session,item,_directory,tasks=_current_session_scope(); task,blocked=_commit_readiness(session,item,tasks,args[1])
                if blocked: print(blocked); return 65
                if session.get("request_ref") is not None:
                    try:
                        decision=_shared_request_decision(session,item,tasks,args[1])
                    except ValueError as exc:
                        print(str(exc)); return 65
                    if decision is None or decision.get("decision")!="COMMIT_REQUIRED" or decision.get("feature")!=item["id"] or decision.get("task")!=args[1]:
                        print(f"BLOCK_SHARED_REQUEST_DECISION:{decision.get('reason') if isinstance(decision,dict) else 'invalid'}"); return 65
                paths,reviewed_tree,blocked=_review_candidate(session,item)
                if blocked: print(blocked); return 65
                if local_commit_requires_manual_git(): print("BLOCK_ACTIVE_GIT_POLICY_REQUIRE_MANUAL_COMMIT"); return 65
                candidate_digests={path:path_digest(path) for path in paths}; initial_status=status_entries()
                incomplete=[entry["id"] for entry in tasks if not entry["complete"]]; next_feature=None
                next_task_directory=None; next_task_ids=None; next_task_digest=None
                if not incomplete and session["follow_on"]:
                    candidate=session["follow_on"][0]; document=feature_document(); successor=next((entry for entry in document["features"] if entry.get("id")==candidate),None)
                    if session.get("request_ref") is not None:
                        try:
                            successor_decision=_shared_request_successor(session,item,tasks)
                        except ValueError as exc:
                            print(str(exc)); return 65
                        if successor_decision is not None and successor_decision.get("decision")=="DEFER" and successor_decision.get("feature")==candidate:
                            # A bounded optional phase may close the request
                            # without activating its next optional member.
                            # The paired terminal transaction records the
                            # explicit deferral before it publishes zero active
                            # features.
                            candidate=None
                        elif successor_decision is not None and successor_decision.get("decision") in {"STOP","COMPLETE"}:
                            # A task/feature/limited-features boundary still
                            # commits the current work, then stops without
                            # activating a successor.
                            candidate=None
                        elif successor_decision is None or successor_decision.get("decision")!="ADVANCE_REQUIRED" or successor_decision.get("feature")!=candidate:
                            print(f"BLOCK_SHARED_REQUEST_SUCCESSOR:{successor_decision.get('reason') if isinstance(successor_decision,dict) else 'invalid'}"); return 65
                    if candidate is not None:
                        states={entry.get("id"):entry.get("status") for entry in document["features"]}; states[item["id"]]="passing"
                        if successor is None or successor.get("status")!="not_started" or any(states.get(dep)!="passing" for dep in successor.get("depends_on",[])): print("BLOCK_INVALID_REQUESTED_SUCCESSOR"); return 65
                        try: next_task_directory,next_task_ids,next_task_digest=_declared_successor_scope(successor)
                        except ValueError: print("BLOCK_REQUESTED_SUCCESSOR_SCOPE_REQUIRED"); return 65
                        next_feature=candidate
                parent=git("rev-parse","HEAD").decode().strip(); index_path=Path(git("rev-parse","--git-path","index").decode().strip())
                if not index_path.is_file(): print("BLOCK_GIT_INDEX_REQUIRED"); return 65
                token=index_token(index_path); index_name=f"commit-index-{session['receipt_key'][:16]}"; temp_index=str(git_dir()/index_name)
                try: os.unlink(temp_index)
                except FileNotFoundError: pass
                try:
                    git_with_index(temp_index,"read-tree","HEAD")
                    if paths: git_with_index(temp_index,"add","--",*paths)
                    staged_paths=[path.decode("utf-8","surrogateescape") for path in git_with_index(temp_index,"diff","--cached","--name-only","-z").split(b"\0") if path]
                    if staged_paths!=paths or candidate_digests!={path:path_digest(path) for path in paths} or initial_status!=status_entries(): print("BLOCK_CANDIDATE_CHANGED_DURING_COMMIT"); return 65
                    tree=git_with_index(temp_index,"write-tree").decode().strip()
                    if tree!=reviewed_tree: print("BLOCK_CANDIDATE_CHANGED_DURING_COMMIT"); return 65
                    expected=git_with_index_input(temp_index,(args[3]+"\n").encode(),"commit-tree",tree,"-p",parent).decode().strip(); prepared_index_digest=hashlib.sha256(Path(temp_index).read_bytes()).hexdigest()
                    pending={"schema":1,"state":"pending","task":task["id"],"parent_head":parent,"committed_head":None,"candidate_tree":tree,"expected_commit":expected,"message_digest":hashlib.sha256((args[3]+"\n").encode()).hexdigest(),"index_name":index_name,"index_token":token,"prepared_index_digest":prepared_index_digest,"lock_identity":None,"hook_digest":commit_hook_digest(),"next_task":incomplete[0] if incomplete else None,"next_feature":next_feature,"next_task_directory":next_task_directory,"next_task_ids":next_task_ids,"next_task_digest":next_task_digest,"execution_mode":session["execution_mode"],"feature_limit":session["feature_limit"],"completed_features":session["completed_features"],"request_queue":session["follow_on"]}
                    session["commit_handoff"]=pending
                    if (session.get("state_handoff") or {}).get("operation")=="record-content":
                        session["state_handoff"]=None
                    publish_session(session,replace=True)
                    if candidate_digests!={path:path_digest(path) for path in paths} or initial_status!=status_entries() or index_token(index_path)!=token:
                        session["commit_handoff"]=None; publish_session(session,replace=True); print("BLOCK_CANDIDATE_CHANGED_DURING_COMMIT"); return 65
                    unclaimed_session_digest=_session_payload_digest(session)
                    reservation=reserve_prepared_index(index_name,token,tree,prepared_index_digest)
                    if not reservation:
                        session["commit_handoff"]=None; publish_session(session,replace=True); print("BLOCK_GIT_INDEX_CHANGED"); return 65
                    lock,descriptor,identity=reservation
                    current,blocked=_claimed_initial_session("commit_handoff",unclaimed_session_digest,pending,lock,descriptor,identity)
                    if blocked: print(blocked); return 65
                    pending=current["commit_handoff"]; pending["lock_identity"]=f"{identity[0]}:{identity[1]}"; current["commit_handoff"]=pending
                    claimed_session_digest=_session_payload_digest(current)
                    try: publish_session(current,replace=True)
                    except ValueError:
                        _cleanup_failed_initial_index_claim("commit_handoff",unclaimed_session_digest,claimed_session_digest,pending,lock,descriptor,identity); raise
                    session.clear(); session.update(current)
                    if candidate_digests!={path:path_digest(path) for path in paths} or initial_status!=status_entries() or not prepared_index_matches_tree(lock,tree,prepared_index_digest) or local_commit_requires_manual_git() or pending["hook_digest"]!=commit_hook_digest():
                        _release_exact_initial_claim_for_retry("commit_handoff",pending,lock,descriptor,identity,expected_session_digest=claimed_session_digest)
                        print("BLOCK_CANDIDATE_CHANGED_DURING_COMMIT"); return 65
                    current,blocked=_late_initial_ref_authority("commit_handoff",pending,lock,descriptor,identity,claimed_session_digest)
                    if blocked: print(blocked); return 65
                    session.clear(); session.update(current); pending=session["commit_handoff"]
                    if required_review_stages(item):
                        _publish_commit_evidence_origin(session,item,expected,tree,parent)
                        current,blocked=_late_initial_ref_authority("commit_handoff",pending,lock,descriptor,identity,claimed_session_digest)
                        if blocked: print(blocked); return 65
                        session.clear(); session.update(current); pending=session["commit_handoff"]
                    try: git("update-ref","HEAD",expected,parent)
                    except ValueError:
                        _release_exact_initial_claim_for_retry("commit_handoff",pending,lock,descriptor,identity,expected_session_digest=claimed_session_digest); raise
                    committed=git("rev-parse","HEAD").decode().strip()
                    if committed!=expected or not finalize_prepared_index_reservation(lock,descriptor,identity,tree,prepared_index_digest): print(json.dumps({"schema":1,"decision":"COMMITTED_HANDOFF_RECOVERY_REQUIRED","committed_head":committed,"task":task["id"]},sort_keys=True)); return 65
                except ValueError:
                    raise
                pending["state"]="committed"; pending["committed_head"]=committed; session["commit_handoff"]=pending
                try: _publish_committed_handoff(session,pending); publish_session(session,replace=True); append_decision_record(session,"local-commit",task["id"],"guarded local commit created")
                except ValueError:
                    print(json.dumps({"schema":1,"decision":"COMMITTED_HANDOFF_PUBLICATION_REQUIRED","committed_head":committed,"task":task["id"]},sort_keys=True)); return 65
                blocked=_record_midtask_content(session)
                if blocked: print(blocked); return 65
                if pending["next_task"] is not None:
                    decision="COMMITTED_STOP_BOUNDARY" if session["execution_mode"]=="task" else ("COMMITTED_CONTINUE_FEATURE" if session["execution_mode"]=="feature" else ("COMMITTED_CONTINUE_FEATURES" if session["execution_mode"]=="features" else "COMMITTED_CONTINUE_REQUEST"))
                else:
                    decision=("COMMITTED_CONTINUE_REQUEST" if session["execution_mode"]=="request" else ("COMMITTED_CONTINUE_FEATURES" if session["execution_mode"]=="features" and next_feature is not None else "COMMITTED_STOP_BOUNDARY"))
                print(json.dumps({"schema":1,"decision":decision,"committed_head":committed,"next_task":pending["next_task"],"next_feature":next_feature},sort_keys=True)); return 0
    except ValueError as exc: print(str(exc),file=sys.stderr); return 65


def _record_midtask_content(session: dict[str, Any]) -> str | None:
    """Journal every task commit before allowing its handoff to be replaced."""
    handoff=session.get("commit_handoff")
    if session.get("request_ref") is None or not isinstance(handoff,dict) or handoff.get("next_task") is None:
        return None
    item=current_feature()
    if handoff.get("state")!="committed" or handoff.get("committed_head")!=git("rev-parse","HEAD").decode().strip():
        return "BLOCK_HANDOFF_HEAD_CHANGED"
    path,payload=_request_content_event_payload(session,item,handoff)
    if _installed_local_state_binding() is not None:
        blocked=_prepare_local_state_transition(session,{path:payload},"record-content")
        if blocked: return blocked
        journal=_local_transition_read()
        _finished,finish_error=_ensure_local_record_content_session(session,journal if isinstance(journal,dict) else {})
        if finish_error: return finish_error
        return None
    _head,blocked=_prepare_generated_state_commit(session,{path:payload},f"{item['id']} record content {handoff['committed_head']}","record-content",None)
    if blocked:
        return blocked
    _refresh_pristine_continuation(session,item,retain_state_handoff=True)
    return None


def _refresh_pristine_continuation(session: dict[str, Any], item: dict[str, Any], *, retain_state_handoff: bool = False, rotation_intent: dict[str, Any] | None = None, local_record_content: bool = False, pre_publish_check: Callable[[],None] | None = None) -> dict[str, Any]:
    record_content=local_record_content or (retain_state_handoff and (session.get("state_handoff") or {}).get("operation")=="record-content")
    if status_entries(refresh_index=not record_content): raise ValueError("BLOCK_PRISTINE_HANDOFF_REQUIRED")
    state=session.get("state_handoff")
    if retain_state_handoff and isinstance(state,dict) and state.get("operation")=="record-content":
        intent=rotation_intent if rotation_intent is not None else _read_rotation_intent(state)
        if intent is not None:
            # The intent may have appeared after the initial recovery snapshot.
            # Validate it against the immutable request binding immediately
            # before installing its successor session.
            binding_session=_rotation_binding_session(session,state,intent)
            _require_request_binding("request-state-"+state["expected_commit"]+".json",_request_state_binding(binding_session,state))
            _publish_owner_baseline(intent["new_session"])
            session.clear(); session.update(intent["new_session"]); publish_session(session,replace=True)
            append_decision_record(session,"fresh-pristine-evidence",item["id"],"state transition requires new receipts from its committed baseline")
            return session
    head=git("rev-parse","HEAD").decode().strip(); key=secrets.token_hex(32)
    old_session=json.loads(json.dumps(session))
    planned=json.loads(json.dumps(session)); planned["mode"]="require-pristine"; planned["base_head"]=head; planned["baseline"]=[]
    # Adoption authorizes one exact dirty candidate. Once its content is
    # committed, a schema-14 successor must not keep referring to that journal.
    # Legacy schema-12 sessions retain their closed field set and v1 bindings.
    if planned.get("schema") in {13,14}: planned["adopted_candidate_digest"]=None
    if record_content and not local_record_content:
        key=state.get("rotation_key")
        if not isinstance(key,str) or not re.fullmatch(r"[0-9a-f]{64}",key): raise ValueError("request rotation key is invalid")
    planned["receipt_key"]=key; planned["receipt_namespace"]=f"receipts-{key[:16]}"; planned["review_record"]=None
    if record_content:
        # The generated content-journal commit advances HEAD beyond the
        # completed task's content commit. Retain the state_handoff as the
        # recovery record, but retire the now-superseded task handoff so the
        # next task is not checked against the previous commit.
        planned["commit_handoff"]=None
    if not (retain_state_handoff and isinstance(state,dict) and state.get("operation")=="resolve-review"):
        planned["review_outcomes"]=[]
    if not retain_state_handoff: planned["state_handoff"]=None
    if retain_state_handoff and isinstance(state,dict) and state.get("operation")=="record-content":
        _publish_rotation_intent(state,old_session,planned)
    _publish_owner_baseline(planned)
    session.clear(); session.update(planned); publish_session(session,replace=True,pre_publish_check=pre_publish_check)
    append_decision_record(session,"fresh-pristine-evidence",item["id"],"state transition requires new receipts from its committed baseline")
    return session


def _successor_start_args(session: dict[str, Any], handoff: dict[str, Any], next_feature: str) -> list[str]:
    args=["--require-pristine","--item",next_feature,"--restart","--execution-mode",handoff["execution_mode"]]
    if handoff["execution_mode"]=="features": args.extend(("--max-features",str(handoff["feature_limit"])))
    reference=session.get("request_ref")
    if isinstance(reference,dict):
        # The successor re-derives its queue from the immutable request rather
        # than accepting a mutable legacy --follow-on tail.
        args.extend(("--request",reference["id"]))
    else:
        for candidate in handoff["request_queue"][1:]: args.extend(("--follow-on",candidate))
    if session.get("builder_id"):
        args.extend(("--builder-id",session["builder_id"],"--builder-binding",session["builder_binding_ref"]))
    args.extend(("--local-commit",session["continuation_policy"]["local_commit"],"--review-mode",session["continuation_policy"]["review"]))
    return args


def _ensure_local_successor_session(session: dict[str,Any] | None, journal: dict[str,Any], binding: tuple[bytes,tuple[int,int]]|None=None) -> tuple[bool,str|None]:
    if journal.get("operation")!="activate-successor": return False,None
    if not isinstance(session,dict): return False,"BLOCK_LOCAL_STATE_TRANSITION_AUTHORITY_CHANGED"
    try:
        ledger_entry=next(entry for entry in journal["entries"] if entry.get("path")==_domain_path("feature_list.json"))
        proposed=json.loads(_local_transition_payload_bytes(ledger_entry).decode("utf-8"))
        pointer_entry=next((entry for entry in journal["entries"] if entry.get("path")==_domain_path(".specify/feature.json")),None)
        pointer=_strict_request_json(_local_transition_payload_bytes(pointer_entry)).get("feature_directory") if pointer_entry else None
        proposed_errors=validation_errors(proposed,project(),active_spec_directory=pointer,proposed_terminal_payloads={entry["path"]:_local_transition_payload_bytes(entry) for entry in journal["entries"]})
        if proposed_errors: raise ValueError("invalid successor ledger")
        successors=[item for item in proposed.get("features",[]) if item.get("status")=="in_progress"]
        if len(successors)!=1: raise ValueError("ambiguous successor")
        next_feature=successors[0].get("id")
    except (KeyError,StopIteration,ValueError,UnicodeError,json.JSONDecodeError):
        return False,"BLOCK_LOCAL_STATE_TRANSITION_INVALID"
    if not isinstance(next_feature,str) or current_feature().get("id")!=next_feature:
        return False,"BLOCK_LOCAL_STATE_TRANSITION_AUTHORITY_CHANGED"
    if binding is None:
        current,binding=_local_transition_read_bound()
        if current!=journal: return False,"BLOCK_LOCAL_STATE_TRANSITION_AUTHORITY_CHANGED"
    if session.get("work_item")==next_feature and session.get("base_head")==journal.get("source_head") and session_task_scope_matches(session,current_feature()):
        bound_error=_local_transition_bound_error(journal,binding)
        if bound_error: return False,bound_error
        _local_transition_retire(journal,binding); return True,None
    handoff=session.get("commit_handoff") or {}
    if (handoff.get("state")!="committed" or handoff.get("committed_head")!=journal.get("source_head")
            or handoff.get("next_feature")!=next_feature):
        return False,"BLOCK_LOCAL_STATE_TRANSITION_AUTHORITY_CHANGED"
    successor_scope_error=_pinned_successor_scope_errors(handoff)
    if successor_scope_error: return False,successor_scope_error
    try: trusted_count=_trusted_successor_completed_features(session,handoff)
    except ValueError as exc: return False,str(exc)
    bound_error=_local_transition_bound_error(journal,binding)
    if bound_error: return False,bound_error
    completed_error=_local_transition_completed_error(journal)
    if completed_error: return False,completed_error
    def check_journal() -> None:
        error=_pinned_successor_scope_errors(handoff)
        if error: raise ValueError(error)
        error=_local_transition_bound_error(journal,binding)
        if error: raise ValueError(error)
        error=_local_transition_completed_error(journal)
        if error: raise ValueError(error)
    if _start_session(_successor_start_args(session,handoff,next_feature),trusted_successor_completed_features=trusted_count,
            trusted_successor_session=session,pre_publish_check=check_journal):
        return False,"BLOCK_SUCCESSOR_SESSION_START"
    successor_session=read_session()
    if (not isinstance(successor_session,dict) or successor_session.get("work_item")!=next_feature
        or successor_session.get("base_head")!=journal.get("source_head") or not session_task_scope_matches(successor_session,current_feature())):
        return False,"BLOCK_SUCCESSOR_SESSION_START"
    _local_transition_retire(journal,binding)
    return True,None


def _ensure_local_record_content_session(session: dict[str,Any] | None, journal: dict[str,Any], binding: tuple[bytes,tuple[int,int]]|None=None) -> tuple[bool,str|None]:
    if journal.get("operation")!="record-content": return False,None
    if not isinstance(session,dict): return False,"BLOCK_LOCAL_STATE_TRANSITION_AUTHORITY_CHANGED"
    head=journal.get("source_head")
    if not isinstance(head,str) or not re.fullmatch(r"[0-9a-f]{40}",head) or git("rev-parse","HEAD").decode().strip()!=head:
        return False,"BLOCK_LOCAL_STATE_TRANSITION_AUTHORITY_CHANGED"
    if binding is None:
        current,binding=_local_transition_read_bound()
        if current!=journal: return False,"BLOCK_LOCAL_STATE_TRANSITION_AUTHORITY_CHANGED"
    if session.get("base_head")==head and session.get("commit_handoff") is None:
        bound_error=_local_transition_bound_error(journal,binding)
        if bound_error: return False,bound_error
        _local_transition_retire(journal,binding); return True,None
    handoff=session.get("commit_handoff") or {}
    if handoff.get("state")!="committed" or handoff.get("committed_head")!=head:
        return False,"BLOCK_LOCAL_STATE_TRANSITION_AUTHORITY_CHANGED"
    bound_error=_local_transition_bound_error(journal,binding)
    if bound_error: return False,bound_error
    completed_error=_local_transition_completed_error(journal)
    if completed_error: return False,completed_error
    def check_journal() -> None:
        error=_local_transition_bound_error(journal,binding)
        if error: raise ValueError(error)
        error=_local_transition_completed_error(journal)
        if error: raise ValueError(error)
    try: _refresh_pristine_continuation(session,current_feature(),local_record_content=True,pre_publish_check=check_journal)
    except ValueError as exc: return False,str(exc)
    _local_transition_retire(journal,binding)
    return True,None


def _trusted_successor_completed_features(session: dict[str, Any], handoff: dict[str, Any]) -> int | None:
    """Carry a legacy bounded counter only from its validated commit handoff."""
    if session.get("request_ref") is not None or handoff.get("execution_mode")!="features":
        return None
    prior=handoff.get("completed_features"); limit=handoff.get("feature_limit")
    if handoff.get("state")!="committed" or isinstance(prior,bool) or not isinstance(prior,int) or prior<0 or isinstance(limit,bool) or not isinstance(limit,int) or limit<1 or handoff.get("completed_features")!=session.get("completed_features") or handoff.get("execution_mode")!=session.get("execution_mode") or handoff.get("feature_limit")!=session.get("feature_limit") or prior+1>=limit:
        raise ValueError("validated legacy successor counter is invalid")
    return prior+1


def _advance_execution_boundary_error(handoff: dict[str, Any], *, terminal: bool) -> str | None:
    """Allow review resolution at a feature boundary without opening successors."""
    mode=handoff.get("execution_mode")
    if mode in {"request","features"} or (mode=="feature" and terminal):
        return None
    return "BLOCK_EXECUTION_BOUNDARY"


def _review_state_binding_matches(session: dict[str, Any], state: dict[str, Any]) -> bool:
    """Validate current votes against the immutable prepared review artifact."""
    current=review_outcomes_digest(session.get("review_outcomes",[]))
    retained=state.get("review_outcomes_digest")
    review_paths=[path for path in state.get("paths",[]) if isinstance(path,str) and path.startswith(_domain_path("harness/reviews")+"/")]
    if len(review_paths)!=1:
        return False
    payload=_git_file(state.get("expected_commit"),review_paths[0]) if isinstance(state.get("expected_commit"),str) else None
    if payload is None:
        return False
    try:
        document=json.loads(payload.decode("utf-8"))
    except (UnicodeDecodeError,json.JSONDecodeError):
        return False
    outcomes=document.get("outcomes") if isinstance(document,dict) else None
    if not isinstance(outcomes,list):
        return False
    artifact_digest=review_outcomes_digest(outcomes)
    return artifact_digest==current and (retained is None or retained==artifact_digest)


def _review_retirement_state_matches(session: dict[str, Any], state: Any) -> bool:
    """Allow only a durable successor/terminal handoff to retire old reviews.

    The state descriptor is published before any generated bytes and binds the
    exact review list.  Recovery can therefore finish that one transition, but
    an interrupted preparation or a changed review record still fails closed.
    """
    if not isinstance(state,dict) or state.get("operation") not in {"activate-successor","complete-request"}:
        return False
    if state_handoff_errors(state,session):
        return False
    if session.get("review_record") is not None:
        return False
    outcomes=session.get("review_outcomes")
    if state.get("review_retirement_digest") != review_outcomes_digest(outcomes):
        return False
    try:
        if state.get("receipt_set_digest") != evidence_digest(session):
            return False
    except ValueError:
        return False
    try:
        if not outcomes or not all(isinstance(entry,dict) and entry.get("source_commit")==outcomes[0].get("source_commit") for entry in outcomes):
            return False
        source_commit=outcomes[0]["source_commit"]
        source_bytes=_git_file(source_commit,"feature_list.json",domain=STATE_DOMAIN)
        if source_bytes is None: return False
        document=_strict_request_json(source_bytes)
        item=next((entry for entry in document.get("features",[]) if entry.get("id")==session.get("work_item")),None)
        if not isinstance(item,dict):
            return False
        expected=required_review_stages(item)
        artifact=_git_file(state["parent_head"],f"harness/reviews/{source_commit}.json")
        if artifact is None:
            return False
        review_artifact=_strict_request_json(artifact)
        if review_artifact.get("outcomes") != outcomes or review_outcomes_digest(review_artifact.get("outcomes")) != state.get("review_retirement_digest"):
            return False
        if review_outcomes_errors(outcomes,session) or [entry.get("stage") for entry in outcomes] != expected:
            return False
        for record in outcomes:
            if record.get("stage")=="code_reviewer" and review_quality_readiness_errors(record.get("quality_assessment")):
                return False
            if record.get("stage")=="final_authority" and record.get("quality_assessment",{}).get("decision") not in {"approval","advisory"}:
                return False
        if git("rev-parse",state["expected_commit"]+"^{tree}").decode().strip()!=state["candidate_tree"] or git("rev-parse",state["expected_commit"]+"^").decode().strip()!=state["parent_head"]:
            return False
        head=git("rev-parse","HEAD").decode().strip()
        # recover_commit independently verifies pending generated bytes before
        # it can publish; this binding only determines whether stale predecessor
        # review evidence may be retired for that exact recovery.
        return (state.get("state")=="pending" and head in {state["parent_head"],state["expected_commit"]}) or (state.get("state")=="committed" and head==state["expected_commit"] and state.get("committed_head")==head)
    except (KeyError,ValueError):
        return False


def _resume_state_handoff(session: dict[str, Any], state: dict[str, Any], rotation_intent: dict[str, Any] | None = None) -> tuple[str | None,str | None]:
    if state_handoff_errors(state,session) or state.get("state")!="committed" or state.get("committed_head")!=git("rev-parse","HEAD").decode().strip(): return None,"BLOCK_STATE_HANDOFF_CHANGED"
    if state["operation"]=="resolve-review":
        if not _review_state_binding_matches(session,state):
            return None,"BLOCK_REVIEW_STATE_CHANGED"
        _refresh_pristine_continuation(session,current_feature(),retain_state_handoff=True,rotation_intent=rotation_intent); return "RECOVERED_REVIEW_RESOLUTION",None
    if state["operation"]=="record-content":
        if session.get("base_head")!=state["committed_head"]:
            _refresh_pristine_continuation(session,current_feature(),retain_state_handoff=True,rotation_intent=rotation_intent)
        return "RECOVERED_CONTENT_RECORD",None
    original=session.get("commit_handoff"); next_feature=state.get("next_feature")
    if next_feature is None:
        return "RECOVERED_REQUEST_TERMINAL",None
    if not isinstance(original,dict) or commit_handoff_errors(original,session) or original.get("state")!="committed" or original.get("next_feature")!=next_feature or current_feature().get("id")!=next_feature or not isinstance(next_feature,str): return None,"BLOCK_SUCCESSOR_HANDOFF_CHANGED"
    if _pinned_successor_scope_errors(original): return None,"BLOCK_REQUESTED_SUCCESSOR_SCOPE_CHANGED"
    try: pointer_directory,pointer_tasks=_active_task_scope(current_feature())
    except ValueError:
        return None,"BLOCK_SUCCESSOR_POINTER_CHANGED"
    if pointer_directory!=original.get("next_task_directory") or [task["id"] for task in pointer_tasks]!=original.get("next_task_ids"):
        return None,"BLOCK_SUCCESSOR_POINTER_CHANGED"
    try:
        trusted_count=_trusted_successor_completed_features(session,original)
    except ValueError:
        return None,"BLOCK_SUCCESSOR_HANDOFF_CHANGED"
    if _start_session(_successor_start_args(session,original,next_feature),trusted_successor_completed_features=trusted_count,
            trusted_successor_session=session): return None,"BLOCK_SUCCESSOR_SESSION_START"
    return "RECOVERED_SUCCESSOR_ACTIVATION",None


def advance(args: list[str]) -> int:
    if args: print("Usage: bin/agent-session advance",file=sys.stderr); return 64
    # The final task handoff owns the ordered review pipeline. Run the adapter
    # before taking the transaction lock because each authenticated review
    # record is published by its own harness invocation.
    try:
        pending_session=read_session()
        pending_handoff=pending_session.get("commit_handoff") if isinstance(pending_session,dict) else None
        pending_local=_local_transition_read()
        review_resolution=pending_session.get("state_handoff") if isinstance(pending_session,dict) else None
        resolved_local_review=False
        if (isinstance(pending_local,dict) and pending_local.get("operation")=="resolve-review"
                and pending_local.get("state")=="retired" and isinstance(pending_session,dict)
                and isinstance(pending_handoff,dict)
                and pending_local.get("source_head")==pending_handoff.get("committed_head")
                and _installed_local_state_binding() is not None):
            # The review journal retains the source receipt key while the
            # completion session rotates to a new key. Authenticate the
            # retained review and its origin before suppressing redispatch.
            rotated=(pending_local.get("receipt_key")!=pending_session.get("receipt_key"))
            if not rotated or (pending_session.get("mode")=="require-pristine"
                    and pending_session.get("baseline")==[]
                    and pending_session.get("base_head")==pending_handoff.get("committed_head")):
                outcomes,blocked=_review_resolution_ready(pending_session,current_feature(),pending_handoff)
                resolved_local_review=blocked is None and outcomes==[]
        if (not (isinstance(pending_local,dict) and pending_local.get("state") in {"pending","complete"})
                and not (isinstance(review_resolution,dict) and review_resolution.get("operation")=="resolve-review")
                and not resolved_local_review
                and isinstance(pending_session,dict) and pending_session.get("continuation_policy",{}).get("review")=="agent"
                and isinstance(pending_handoff,dict) and pending_handoff.get("state")=="committed" and pending_handoff.get("next_task") is None):
            dispatch_status=review_dispatch_command([])
            if dispatch_status: return dispatch_status
    except (KeyError,OSError,ValueError) as exc:
        print("BLOCK_REVIEW_DISPATCH_FAILED: "+str(exc),file=sys.stderr); return 65
    try:
        with admin_transaction():
            with local_commit_lock():
                pending_local,pending_binding=_local_transition_read_bound()
                if isinstance(pending_local,dict) and pending_local.get("state")=="complete":
                    integrity_error=_local_transition_completed_error(pending_local)
                    if integrity_error: print(integrity_error); return 65
                if isinstance(pending_local,dict) and pending_local.get("state")=="pending":
                    prior_operation=pending_local.get("operation"); session_before=read_session()
                    _decision,local_blocked=_resume_local_state_transition(session_before)
                    if local_blocked: print(local_blocked); return 65
                    if prior_operation=="resolve-review":
                        resolved_journal,resolved_binding=_local_transition_read_bound()
                        if isinstance(resolved_journal,dict) and resolved_journal.get("state")=="complete": _local_transition_retire(resolved_journal,resolved_binding)
                    if prior_operation!="resolve-review":
                        if prior_operation=="complete-request":
                            _retire_completed_local_request(); activation_error=None
                        elif prior_operation=="record-content":
                            _finished,activation_error=_ensure_local_record_content_session(session_before,_local_transition_read() or pending_local)
                        else: _finished,activation_error=_ensure_local_successor_session(session_before,_local_transition_read() or pending_local)
                        if activation_error: print(activation_error); return 65
                        print(json.dumps({"schema":1,"decision":"RECOVERED_LOCAL_STATE_TRANSITION","committed_head":git("rev-parse","HEAD").decode().strip()},sort_keys=True)); return 0
                elif isinstance(pending_local,dict) and pending_local.get("state")=="complete" and pending_local.get("operation")=="activate-successor":
                    session_before=read_session(); _activated,activation_error=_ensure_local_successor_session(session_before,pending_local,pending_binding)
                    if activation_error: print(activation_error); return 65
                    print(json.dumps({"schema":1,"decision":"RECOVERED_SUCCESSOR_ACTIVATION","committed_head":git("rev-parse","HEAD").decode().strip()},sort_keys=True)); return 0
                elif isinstance(pending_local,dict) and pending_local.get("state")=="complete" and pending_local.get("operation")=="resolve-review":
                    _local_transition_retire(pending_local,pending_binding)
                    print(json.dumps({"schema":1,"decision":"RECOVERED_LOCAL_STATE_TRANSITION","committed_head":git("rev-parse","HEAD").decode().strip()},sort_keys=True)); return 0
                elif isinstance(pending_local,dict) and pending_local.get("state")=="complete" and pending_local.get("operation")=="record-content":
                    _finished,finish_error=_ensure_local_record_content_session(read_session(),pending_local,pending_binding)
                    if finish_error: print(finish_error); return 65
                    print(json.dumps({"schema":1,"decision":"RECOVERED_LOCAL_STATE_TRANSITION","committed_head":git("rev-parse","HEAD").decode().strip()},sort_keys=True)); return 0
                elif isinstance(pending_local,dict) and pending_local.get("state")=="complete" and pending_local.get("operation")=="complete-request":
                    _retire_completed_local_request(pending_local,pending_binding)
                    print(json.dumps({"schema":1,"decision":"RECOVERED_LOCAL_STATE_TRANSITION","committed_head":git("rev-parse","HEAD").decode().strip()},sort_keys=True)); return 0
                session,item,_directory,tasks=_current_session_scope(); _require_owner_baseline(session); handoff=session.get("commit_handoff")
                readiness_errors=session_review_readiness_errors(session)
                if readiness_errors:
                    print("BLOCK_UNRESOLVED_MATERIAL_REVIEW\n"+"\n".join(readiness_errors)); return 65
                if session["source_policy_digest"]!=execution_policy_digest(): print("BLOCK_STALE_CONTINUATION_POLICY"); return 65
                if session.get("request_ref") is not None:
                    decision=request_decision(session)
                    allowed={"RECOVER_REQUIRED"}
                    if isinstance(handoff,dict) and handoff.get("state")=="committed":
                        allowed.update({"ADVANCE_REQUIRED","DEFER","COMPLETE"})
                    if decision.get("decision") not in allowed: print(f"BLOCK_SHARED_REQUEST_DECISION:{decision.get('reason')}"); return 65
                if not isinstance(handoff,dict) or handoff.get("state")!="committed": print("BLOCK_COMMITTED_HANDOFF_REQUIRED"); return 65
                successor_block=_pinned_successor_scope_errors(handoff)
                if successor_block: print(successor_block); return 65
                state=session.get("state_handoff"); resolved_review_head=None; fresh_baseline=False; retry_receipts=False
                if isinstance(state,dict) and state.get("state")=="pending": print("BLOCK_STATE_RECOVERY_REQUIRED"); return 65
                if isinstance(state,dict) and state.get("state")=="committed":
                    if state.get("operation")!="resolve-review" or state.get("committed_head")!=git("rev-parse","HEAD").decode().strip(): print("BLOCK_STATE_HANDOFF_CHANGED"); return 65
                    if not _review_state_binding_matches(session,state): print("BLOCK_REVIEW_STATE_CHANGED"); return 65
                    resolved_review_head=state["committed_head"]
                    if session.get("mode")=="require-pristine" and session.get("baseline")==[] and session.get("base_head")==resolved_review_head:
                        # An exact committed retry already owns its pristine
                        # receipt namespace. Keep it so a completed signed run
                        # is not repeated merely by invoking advance again.
                        _require_owner_baseline(session); retry_receipts=True; fresh_baseline=True
                    else:
                        session=_refresh_pristine_continuation(session,current_feature(),retain_state_handoff=True); item=current_feature()
                        fresh_baseline=True
                head=git("rev-parse","HEAD").decode().strip()
                if (resolved_review_head or handoff.get("committed_head"))!=head: print("BLOCK_HANDOFF_HEAD_CHANGED"); return 65
                next_feature=handoff.get("next_feature")
                terminal=next_feature is None
                boundary_error=_advance_execution_boundary_error(handoff,terminal=terminal)
                if boundary_error: print(boundary_error); return 65
                if handoff["execution_mode"]=="features" and handoff["completed_features"]+1>=handoff["feature_limit"]: print("BLOCK_FEATURE_LIMIT"); return 65
                if not terminal and (not handoff["request_queue"] or handoff["request_queue"][0]!=next_feature): print("BLOCK_REQUEST_QUEUE_CHANGED"); return 65
                successor_block=_pinned_successor_scope_errors(handoff)
                if successor_block: print(successor_block); return 65
                clean_revalidation=_clean_revalidation_head_candidate(session,item)
                if status_entries() and not clean_revalidation: print("BLOCK_PRISTINE_HANDOFF_REQUIRED"); return 65
                outcomes,blocked=_review_resolution_ready(session,item,handoff)
                if blocked: print(blocked); return 65
                if outcomes:
                    payloads=_review_resolution_payloads(item,handoff,outcomes,session)
                    if _installed_local_state_binding() is not None:
                        blocked=_prepare_local_state_transition(session,payloads,"resolve-review")
                        committed=git("rev-parse","HEAD").decode().strip()
                    else:
                        committed,blocked=_prepare_generated_state_commit(session,payloads,f"{item['id']} resolve independent review", "resolve-review",next_feature,allow_matching_dirty=clean_revalidation)
                    if blocked:
                        print(json.dumps({"schema":1,"decision":"LOCAL_STATE_RECOVERY_REQUIRED" if blocked.startswith("BLOCK_LOCAL_STATE") else "STATE_RECOVERY_REQUIRED" if blocked=="RECOVERY_REQUIRED" else blocked,"blocker":blocked,"committed_head":committed,"next_feature":next_feature},sort_keys=True)); return 65
                    if _installed_local_state_binding() is not None:
                        resolved_journal,resolved_binding=_local_transition_read_bound()
                        if isinstance(resolved_journal,dict) and resolved_journal.get("operation")=="resolve-review" and resolved_journal.get("state")=="complete": _local_transition_retire(resolved_journal,resolved_binding)
                    session=_refresh_pristine_continuation(session,current_feature(),retain_state_handoff=True); item=current_feature()
                    fresh_baseline=True; resolved_review_head=git("rev-parse","HEAD").decode().strip(); retry_receipts=True
                local_review_pending = False
                if not fresh_baseline and _installed_local_state_binding() is not None and session.get("review_outcomes"):
                    _review_outcomes,_review_blocked=_review_resolution_ready(session,item,handoff)
                    local_review_pending=_review_blocked is None and bool(_review_outcomes)
                if not fresh_baseline and not local_review_pending:
                    session=_refresh_pristine_continuation(session,item); item=current_feature()
                if retry_receipts:
                    if _installed_local_state_binding() is not None:
                        # Local review resolution is authenticated by its private
                        # journal and ledger/review digests; it deliberately has
                        # no synthetic Git child commit for _origin_receipts.
                        reusable=None
                    else:
                        try: reusable=_origin_receipts(handoff.get("committed_head",""),resolved_review_head,item) if resolved_review_head else None
                        except ValueError as exc: print(str(exc)); return 65
                    if reusable is not None: pass
                    elif not _current_evidence_errors(session,item): pass
                    elif _verify_profiles(item["required_profiles"]): return 65
                elif _current_evidence_errors(session,item) and _verify_profiles(item["required_profiles"]): return 65
                successor_block=_pinned_successor_scope_errors(handoff)
                if successor_block: print(successor_block); return 65
                generated=_mark_passing(next_feature,handoff["next_task_directory"],deferred_payloads=True)
                if isinstance(generated,int): return generated
                if session.get("request_ref") is not None:
                    try:
                        completion_document=json.loads(generated[_domain_path("feature_list.json")].decode("utf-8"))
                        event_path,event_payload=_request_content_event_payload(session,item,handoff,completion_document=completion_document,completion_payloads=generated,terminal=terminal)
                    except ValueError as exc:
                        print(str(exc)); return 65
                    generated[event_path]=event_payload
                    if terminal:
                        proposed_request=_strict_request_json(event_payload)
                        pair_errors=_terminal_request_pair_errors(proposed_request,completion_document,proposed_payloads=generated)
                        pair_errors.extend(request_event_git_errors(proposed_request,generated=True))
                        pair_errors.extend(validation_errors(completion_document,project(),proposed_terminal_request=proposed_request,proposed_terminal_payloads=generated))
                        if pair_errors:
                            print("\n".join(sorted(set(pair_errors))),file=sys.stderr); return 65
                if _installed_local_state_binding() is not None:
                    blocked=_prepare_local_state_transition(session,generated,"complete-request" if terminal else "activate-successor")
                    state_commit=git("rev-parse","HEAD").decode().strip()
                    if blocked:
                        print(json.dumps({"schema":1,"decision":"LOCAL_STATE_RECOVERY_REQUIRED" if blocked.startswith("BLOCK_LOCAL_STATE") else blocked,"blocker":blocked,"committed_head":state_commit,"next_feature":next_feature},sort_keys=True)); return 65
                    if terminal:
                        _retire_completed_local_request()
                    else:
                        completed_local,completed_binding=_local_transition_read_bound()
                        _activated,activation_error=_ensure_local_successor_session(session,completed_local or {},completed_binding)
                        if activation_error: print(activation_error); return 65
                        if not _activated: print("BLOCK_SUCCESSOR_SESSION_START"); return 65
                    print(json.dumps({"schema":1,"decision":"ADVANCED_LOCAL_STATE","committed_head":state_commit,"next_feature":next_feature},sort_keys=True)); return 0
                state_commit,blocked=_prepare_generated_state_commit(session,generated,f"{item['id']} {'complete request' if terminal else 'activate '+next_feature}","complete-request" if terminal else "activate-successor",next_feature)
                if blocked:
                    print(json.dumps({"schema":1,"decision":"STATE_RECOVERY_REQUIRED" if blocked=="RECOVERY_REQUIRED" else blocked,"committed_head":state_commit,"next_feature":next_feature},sort_keys=True)); return 65
                decision,blocked=_resume_state_handoff(session,session["state_handoff"])
                if blocked: print(blocked); return 65
                print(json.dumps({"schema":1,"decision":"ADVANCED_REQUEST","committed_head":git("rev-parse","HEAD").decode().strip(),"next_feature":next_feature},sort_keys=True)); return 0
    except ValueError as exc: print(str(exc),file=sys.stderr); return 65


def _pending_state_matches_worktree(handoff: dict[str, Any]) -> bool:
    """Fail closed unless the retained generated transition is still exact."""
    paths=handoff.get("paths")
    if not isinstance(paths,list):
        return False
    observed={entry["path"] for entry in status_entries()}
    pointer_path=_domain_path(".specify/feature.json")
    if pointer_path in paths:
        try:
            if _pending_live_bytes(pointer_path) is not None:
                observed.add(pointer_path)
        except ValueError:
            return False
    if sorted(observed)!=paths:
        return False
    temporary=git_dir()/f"recovery-index-{handoff['expected_commit'][:16]}"
    try:
        temporary.unlink()
    except FileNotFoundError:
        pass
    try:
        git_with_index(str(temporary),"read-tree",handoff["parent_head"])
        for path in paths:
            current=_pending_live_bytes(path)
            if current is None:
                return False
            blob=git_with_index_input(str(temporary),current,"hash-object","-w","--stdin").decode().strip()
            git_with_index(str(temporary),"update-index","--add","--cacheinfo",f"100644,{blob},{path}")
        staged=[entry.decode("utf-8","surrogateescape") for entry in git_with_index(str(temporary),"diff","--cached","--name-only","-z").split(b"\0") if entry]
        return staged==paths and git_with_index(str(temporary),"write-tree").decode().strip()==handoff["candidate_tree"]
    except ValueError:
        return False
    finally:
        try: temporary.unlink()
        except FileNotFoundError: pass


def _pending_commit_matches_worktree(handoff: dict[str, Any], paths: list[str]) -> bool:
    """Prove that current scoped content still reconstructs the prepared tree."""
    if paths!=sorted(set(paths)):
        return False
    expected_paths=[entry.decode("utf-8","surrogateescape") for entry in git("diff-tree","--no-commit-id","--name-only","-r","-z",handoff["expected_commit"]).split(b"\0") if entry]
    if expected_paths!=paths:
        return False
    temporary=git_dir()/f"recovery-index-{handoff['expected_commit'][:16]}"
    try:
        try: temporary.unlink()
        except FileNotFoundError: pass
        git_with_index(str(temporary),"read-tree",handoff["parent_head"])
        if paths: git_with_index(str(temporary),"add","--",*paths)
        staged=[entry.decode("utf-8","surrogateescape") for entry in git_with_index(str(temporary),"diff","--cached","--name-only","-z").split(b"\0") if entry]
        return staged==paths and git_with_index(str(temporary),"write-tree").decode().strip()==handoff["candidate_tree"]
    except ValueError:
        return False
    finally:
        try: temporary.unlink()
        except FileNotFoundError: pass


def _pending_state_matches_parent(handoff: dict[str, Any]) -> bool:
    """Refuse to replace owner bytes before any generated state publication."""
    for path in handoff["paths"]:
        if not _pending_state_path_matches_parent(handoff,path): return False
    return True


def _pending_live_bytes(path: str) -> bytes | None:
    """Read a pending owner path through no-follow regular-file handles."""
    parts=Path(path).parts; directory_fd=None; descriptor=None
    try:
        directory_fd=open_repo_directory(*parts[:-1])
        try:
            descriptor=os.open(parts[-1],os.O_RDONLY|getattr(os,"O_NOFOLLOW",0)|getattr(os,"O_NONBLOCK",0),dir_fd=directory_fd)
        except FileNotFoundError:
            return None
        metadata=os.fstat(descriptor)
        if not stat.S_ISREG(metadata.st_mode): raise ValueError("nonregular recovery target")
        chunks=[]
        while True:
            chunk=os.read(descriptor,1024*1024)
            if not chunk: break
            chunks.append(chunk)
        return b"".join(chunks)
    except _MissingRepoDirectory:
        return None
    except (OSError,ValueError) as exc:
        if isinstance(exc,ValueError): raise
        raise ValueError("unsafe recovery target") from exc
    finally:
        if descriptor is not None:
            try: os.close(descriptor)
            except OSError: pass
        if directory_fd is not None:
            try: os.close(directory_fd)
            except OSError: pass


def _pending_state_path_matches_parent(handoff: dict[str, Any], path: str) -> bool:
    try: current=_pending_live_bytes(path)
    except ValueError: return False
    parent=_git_file(handoff["parent_head"],path)
    expected_commit=handoff.get("expected_commit")
    desired=_git_file(expected_commit,path) if expected_commit else None
    if current is None and parent is None:
        return True
    if current==parent or current==desired:
        return True
    # The SpecKit pointer is intentionally ignored in some repositories, so its
    # exact live preimage is carried in the durable activation plan.
    return path==_domain_path(".specify/feature.json") and current is not None and hashlib.sha256(current).hexdigest()==handoff.get("pointer_preimage")


def _materialize_pending_state(handoff: dict[str, Any]) -> bool:
    """Complete only parent-or-desired generated bytes after a publication crash."""
    for path in handoff["paths"]:
        desired=_git_file(handoff["expected_commit"],path); parent=_git_file(handoff["parent_head"],path)
        if desired is None: return False
        try: current=_pending_live_bytes(path)
        except ValueError: return False
        if current==desired: continue
        if current!=parent:
            # Spec Kit's pointer can be ignored by Git. Its exact preimage was
            # bound in the pending descriptor; never overwrite owner bytes.
            if path!=_domain_path(".specify/feature.json"): return False
            if current is None or hashlib.sha256(current).hexdigest()!=handoff.get("pointer_preimage"): return False
        parts=Path(path).parts; directory_fd=open_repo_directory(*parts[:-1],create=True)
        try: _publish_bytes(directory_fd,parts[-1],desired,replace=True,mode=0o644)
        finally: os.close(directory_fd)
    return True



def _recovery_retirement_revalidation(handoff: dict[str, Any]) -> tuple[dict[str, Any] | None,str | None]:
    """Reload the exact pending retirement descriptor immediately before HEAD."""
    _before_recovery_state_head_publication()
    refreshed=read_session()
    if refreshed is None:
        return None,"BLOCK_REVIEW_RETIREMENT_STATE_CHANGED"
    refreshed_state=refreshed.get("state_handoff")
    if not isinstance(refreshed_state,dict) or refreshed_state!=handoff:
        return refreshed,"BLOCK_REVIEW_RETIREMENT_STATE_CHANGED"
    if not _review_retirement_state_matches(refreshed,refreshed_state):
        return refreshed,"BLOCK_REVIEW_RETIREMENT_STATE_CHANGED"
    if session_review_readiness_errors(refreshed):
        return refreshed,"BLOCK_FINAL_AUTHORITY_INVENTORY_CHANGED"
    return refreshed,None


def recover_commit(args: list[str]) -> int:
    if args: print("Usage: bin/agent-session recover-commit",file=sys.stderr); return 64
    try:
        with admin_transaction():
            with local_commit_lock():
                if (_installed_local_state_binding() is not None
                    and (git_dir()/"lifecycle"/STATE_DOMAIN/"installed-state-transitions").exists()):
                    _restore_local_transition_journal()
                local_journal,local_binding=_local_transition_read_bound()
                if local_journal is not None and local_journal.get("state")!="pending":
                    integrity_error=(_local_transition_completed_error(local_journal) if local_journal.get("state")=="complete"
                                     else _local_transition_integrity_error(local_journal))
                    if integrity_error: print(integrity_error); return 65
                session=read_session(allow_stale_request=isinstance(local_journal,dict) and local_journal.get("state")=="pending")
                if isinstance(local_journal,dict) and local_journal.get("state")=="pending":
                    decision,local_blocked=_resume_local_state_transition(session)
                    if local_blocked: print(local_blocked); return 65
                    session=read_session()
                    completed_journal=_local_transition_read() or local_journal
                    if local_journal.get("operation")=="resolve-review":
                        if completed_journal.get("state")=="complete":
                            completed_journal,completed_binding=_local_transition_read_bound()
                            _local_transition_retire(completed_journal,completed_binding)
                        activation_error=None
                    elif local_journal.get("operation")=="complete-request":
                        _retire_completed_local_request()
                        activation_error=None
                    elif local_journal.get("operation")=="record-content":
                        _finished,activation_error=_ensure_local_record_content_session(session,completed_journal)
                    else: _activated,activation_error=_ensure_local_successor_session(session,completed_journal)
                    if activation_error: print(activation_error); return 65
                    print(json.dumps({"schema":1,"decision":decision or "RECOVERED_LOCAL_STATE_TRANSITION","committed_head":git("rev-parse","HEAD").decode().strip()},sort_keys=True)); return 0
                if isinstance(local_journal,dict) and local_journal.get("state")=="complete" and local_journal.get("operation")=="activate-successor":
                    _activated,activation_error=_ensure_local_successor_session(session,local_journal,local_binding)
                    if activation_error: print(activation_error); return 65
                    print(json.dumps({"schema":1,"decision":"RECOVERED_SUCCESSOR_ACTIVATION","committed_head":git("rev-parse","HEAD").decode().strip()},sort_keys=True)); return 0
                if isinstance(local_journal,dict) and local_journal.get("state")=="complete" and local_journal.get("operation")=="resolve-review":
                    _local_transition_retire(local_journal,local_binding)
                    print(json.dumps({"schema":1,"decision":"RECOVERED_LOCAL_STATE_TRANSITION","committed_head":git("rev-parse","HEAD").decode().strip()},sort_keys=True)); return 0
                if isinstance(local_journal,dict) and local_journal.get("state")=="complete" and local_journal.get("operation")=="record-content":
                    _finished,finish_error=_ensure_local_record_content_session(session,local_journal,local_binding)
                    if finish_error: print(finish_error); return 65
                    print(json.dumps({"schema":1,"decision":"RECOVERED_LOCAL_STATE_TRANSITION","committed_head":git("rev-parse","HEAD").decode().strip()},sort_keys=True)); return 0
                if isinstance(local_journal,dict) and local_journal.get("state")=="complete" and local_journal.get("operation")=="complete-request":
                    _retire_completed_local_request(local_journal,local_binding)
                    print(json.dumps({"schema":1,"decision":"RECOVERED_LOCAL_STATE_TRANSITION","committed_head":git("rev-parse","HEAD").decode().strip()},sort_keys=True)); return 0
                if session is None: print("BLOCK_PREPARED_COMMIT_REQUIRED"); return 65
                state=session.get("state_handoff")
                if not isinstance(state,dict) and not isinstance(session.get("commit_handoff"),dict):
                    print("BLOCK_PREPARED_COMMIT_REQUIRED"); return 65
                if session.get("source_policy_digest")!=execution_policy_digest():
                    print("BLOCK_STALE_CONTINUATION_POLICY"); return 65
                if isinstance(state,dict) and state.get("operation")=="resolve-review" and not _review_state_binding_matches(session,state):
                    print("BLOCK_REVIEW_STATE_CHANGED"); return 65
                if isinstance(state,dict) and state.get("operation")=="resolve-review" and state.get("state")=="pending" and state.get("evidence_digest") != evidence_digest(session):
                    print("BLOCK_REVIEW_EVIDENCE_CHANGED"); return 65
                if isinstance(state,dict) and state.get("state")=="pending" and state.get("operation") != "resolve-review" and not _pending_state_matches_parent(state):
                    print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                readiness_errors=session_review_readiness_errors(session)
                if readiness_errors:
                    print("BLOCK_UNRESOLVED_MATERIAL_REVIEW\n"+"\n".join(readiness_errors)); return 65
                rotation_intent=_read_rotation_intent(state) if isinstance(state,dict) and state.get("operation")=="record-content" and state.get("state")=="committed" else None
                # A committed generated state transition has already pinned its
                # candidate bytes and cannot recreate content.  Pending state
                # can still publish a commit, so it retains the receipt gate.
                state_needs_recovery=isinstance(state,dict) and state.get("state")=="pending"
                if state_needs_recovery:
                    evidence=_recovery_receipt_errors(session)
                elif not isinstance(state,dict):
                    item=current_feature()
                    if session.get("work_item")!=item.get("id") or session.get("profiles")!=item.get("required_profiles"):
                        print("BLOCK_SESSION_SCOPE_CHANGED"); return 65
                    evidence=_current_evidence_errors(session,item)
                else:
                    evidence=[]
                if evidence:
                    print("BLOCK_CURRENT_EVIDENCE_REQUIRED\n"+"\n".join(evidence)); return 65
                if session.get("request_ref") is not None:
                    decision=request_decision(session)
                    completed_retry=isinstance(state,dict) and state.get("state")=="committed" and (state.get("operation")=="record-content" or (state.get("operation")=="complete-request" and decision.get("decision")=="COMPLETE"))
                    if isinstance(state,dict) and state.get("state")=="committed":
                        _prepared_request_snapshot(session,rotation_intent)
                    if decision.get("decision")!="RECOVER_REQUIRED" and not completed_retry: print(f"BLOCK_SHARED_REQUEST_DECISION:{decision.get('reason')}"); return 65
                if isinstance(state,dict) and state.get("state")=="committed":
                    decision,blocked=_resume_state_handoff(session,state,rotation_intent)
                    if blocked: print(blocked); return 65
                    print(json.dumps({"schema":1,"decision":decision,"committed_head":state["committed_head"],"next_feature":state["next_feature"]},sort_keys=True)); return 0
                handoff=state if isinstance(state,dict) and state.get("state")=="pending" else session.get("commit_handoff")
                if session.get("request_ref") is not None and isinstance(handoff,dict) and handoff.get("state")=="committed" and handoff.get("next_task") is not None:
                    blocked=_record_midtask_content(session)
                    if blocked: print(blocked); return 65
                    print(json.dumps({"schema":1,"decision":"RECOVERED_CONTENT_RECORD","committed_head":handoff["committed_head"]},sort_keys=True)); return 0
                if not isinstance(handoff,dict) or handoff.get("state")!="pending": print("BLOCK_PREPARED_COMMIT_REQUIRED"); return 65
                if handoff.get("operation")=="resolve-review" and not _review_state_binding_matches(session,handoff):
                    print("BLOCK_REVIEW_STATE_CHANGED"); return 65
                expected=handoff["expected_commit"]; parent=handoff["parent_head"]; tree=handoff["candidate_tree"]
                payloads={path:_git_file(expected,path) for path in handoff.get("paths",[]) if isinstance(path,str)}
                if git("rev-parse",expected+"^{tree}").decode().strip()!=tree or git("rev-parse",expected+"^" ).decode().strip()!=parent: print("BLOCK_PREPARED_COMMIT_MISMATCH"); return 65
                message=commit_message_bytes(expected)
                if hashlib.sha256(message).hexdigest()!=handoff["message_digest"]: print("BLOCK_PREPARED_COMMIT_MISMATCH"); return 65
                head=git("rev-parse","HEAD").decode().strip()
                if head==parent and handoff is state:
                    # A generated state commit can clear gates or change the
                    # active feature. Recheck independent owner authority before
                    # any pre-ref recovery work is allowed to begin.
                    _require_owner_baseline(session)
                if head==expected and handoff.get("lock_identity") is not None:
                    lock_path=Path(git("rev-parse","--git-path","index").decode().strip()).with_name("index.lock")
                    index_path=Path(git("rev-parse","--git-path","index").decode().strip())
                    if not lock_path.exists() and index_path.is_file() and prepared_index_matches_tree(index_path,tree,hashlib.sha256(index_path.read_bytes()).hexdigest()):
                        handoff["state"]="committed"; handoff["committed_head"]=expected
                        if handoff is state: session["state_handoff"]=handoff
                        else: session["commit_handoff"]=handoff
                        publish_session(session,replace=True)
                        if handoff is state and session.get("request_ref") is not None:
                            decision,blocked=_resume_state_handoff(session,state)
                            if blocked: print(blocked); return 65
                            print(json.dumps({"schema":1,"decision":decision,"committed_head":expected,"next_feature":state["next_feature"]},sort_keys=True)); return 0
                        if handoff is not state:
                            blocked=_record_midtask_content(session)
                            if blocked: print(blocked); return 65
                        print(json.dumps({"schema":1,"decision":"RECOVERED_INDEX_PUBLISHED","committed_head":expected,"next_feature":handoff.get("next_feature")},sort_keys=True)); return 0
                if head==parent and handoff is not state:
                    # A prepared content commit has not published HEAD yet.
                    # Reuse ordinary readiness and scoped path selection before
                    # reserving or mutating recovery state. Rebuild its exact
                    # candidate tree from the current worktree as well.
                    current,item,_directory,tasks=_current_session_scope()
                    if current.get("commit_handoff")!=handoff:
                        print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                    _task,blocked=_commit_readiness(current,item,tasks,handoff["task"])
                    if blocked: print(blocked); return 65
                    recovery_content_paths,recovery_tree,blocked=_review_candidate(current,item)
                    if blocked: print(blocked); return 65
                    if recovery_tree!=tree or not _pending_commit_matches_worktree(handoff,recovery_content_paths): print("BLOCK_CANDIDATE_CHANGED_DURING_RECOVERY"); return 65
                if head==parent and session.get("source_policy_digest")!=execution_policy_digest(): print("BLOCK_STALE_CONTINUATION_POLICY"); return 65
                if head==parent and (handoff["hook_digest"]!=commit_hook_digest() or local_commit_requires_manual_git()): print("BLOCK_ACTIVE_GIT_POLICY_REQUIRE_MANUAL_COMMIT"); return 65
                if head==parent and handoff is state and (not _materialize_pending_state(handoff) or not _pending_state_matches_worktree(handoff)): print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                if head==parent and handoff is state:
                    current_session=read_session()
                    if current_session is None or current_session.get("state_handoff")!=handoff:
                        print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                    session=current_session; state=session["state_handoff"]; handoff=state
                    handoff["index_token"]=index_token(Path(git("rev-parse","--git-path","index").decode().strip()))
                    session["state_handoff"]=handoff; publish_session(session,replace=True)
                if handoff.get("lock_identity"):
                    reservation=claimed_prepared_index_reservation(handoff["index_name"],handoff["index_token"],handoff["lock_identity"],tree,handoff["prepared_index_digest"])
                    if not reservation:
                        # A previously claimed lock may be missing after a
                        # crash between lock removal and clearing its identity.
                        # Reclaim only when the exact prepared authority remains
                        # current and the visible lock path is absent.
                        index_path=Path(git("rev-parse","--git-path","index").decode().strip())
                        lock_path=index_path.with_name(index_path.name+".lock")
                        try: lock_missing=not lock_path.exists() and not lock_path.is_symlink()
                        except OSError: lock_missing=False
                        current_session=read_session()
                        key="state_handoff" if handoff is state else "commit_handoff"
                        current_handoff=current_session.get(key) if isinstance(current_session,dict) else None
                        prepared=git_dir()/handoff["index_name"]
                        if (lock_missing and current_handoff==handoff and index_path.is_file() and index_token(index_path)==handoff["index_token"] and prepared.is_file() and prepared_index_matches_tree(prepared,tree,handoff["prepared_index_digest"])):
                            current_handoff["lock_identity"]=None
                            current_session[key]=current_handoff
                            publish_session(current_session,replace=True)
                            session=current_session
                            if key=="state_handoff": state=current_handoff; handoff=state
                            else: handoff=current_handoff
                            reservation=reserve_prepared_index(handoff["index_name"],handoff["index_token"],tree,handoff["prepared_index_digest"])
                        else:
                            reservation=None
                else:
                    reservation=reserve_prepared_index(handoff["index_name"],handoff["index_token"],tree,handoff["prepared_index_digest"])
                if not reservation: print("BLOCK_PREPARED_INDEX_RECOVERY_REQUIRED"); return 65
                lock,descriptor,identity=reservation
                owned_lock_identity=f"{identity[0]}:{identity[1]}"
                unclaimed_handoff=dict(handoff) if handoff.get("lock_identity") is None else None
                def release_recovery_reservation() -> None:
                    try: retained_session=read_session()
                    except ValueError:
                        os.close(descriptor); return
                    if retained_session is None:
                        os.close(descriptor); return
                    key="state_handoff" if handoff is state else "commit_handoff"
                    retained=retained_session.get(key)
                    if isinstance(retained,dict) and unclaimed_handoff is not None and retained==unclaimed_handoff:
                        # Reservation succeeded but its identity never became
                        # durable. The unchanged handoff cannot claim this
                        # lock, so remove only our exact inode and retry later.
                        os.close(descriptor); _discard_prepared_index_reservation(lock,identity); return
                    if isinstance(retained,dict) and retained.get("lock_identity")==owned_lock_identity and retained==handoff:
                        os.close(descriptor); _discard_prepared_index_reservation(lock,identity)
                        retained["lock_identity"]=None
                        retained_session[key]=retained
                        publish_session(retained_session,replace=True)
                        return
                    if isinstance(retained,dict) and retained.get("lock_identity")==owned_lock_identity:
                        # Another session value now owns the authority. Keep
                        # the exact prepared lock so restoring the claimed
                        # handoff can safely reclaim it.
                        os.close(descriptor); return
                    if handoff.get("lock_identity")==owned_lock_identity:
                        # This call reclaimed a lock already named by the
                        # persisted handoff, or durably published the claim
                        # earlier in this recovery. If that handoff changed
                        # during recovery, retain the inode so exact
                        # restoration can claim it again.
                        os.close(descriptor); return
                    # No persisted handoff names this newly created inode, so
                    # it is ours to release even if the session changed while
                    # reservation was in flight.
                    os.close(descriptor); _discard_prepared_index_reservation(lock,identity)
                if handoff.get("lock_identity") is None:
                    key="state_handoff" if handoff is state else "commit_handoff"
                    try: current_session=read_session()
                    except ValueError:
                        # No durable claim has been published yet. If reading
                        # current authority fails, release only this newly
                        # created inode so the unchanged unclaimed handoff can
                        # retry after the read problem is repaired.
                        os.close(descriptor); _discard_prepared_index_reservation(lock,identity); raise
                    current_handoff=current_session.get(key) if isinstance(current_session,dict) else None
                    if current_handoff!=unclaimed_handoff:
                        os.close(descriptor); _discard_prepared_index_reservation(lock,identity)
                        print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                    current_handoff["lock_identity"]=owned_lock_identity
                    current_session[key]=current_handoff
                    session=current_session
                    if key=="state_handoff": state=current_handoff; handoff=state
                    else: handoff=current_handoff
                    try: publish_session(session,replace=True)
                    except ValueError:
                        release_recovery_reservation(); raise
                if head==parent:
                    if local_commit_requires_manual_git(): release_recovery_reservation(); print("BLOCK_ACTIVE_GIT_POLICY_REQUIRE_MANUAL_COMMIT"); return 65
                    if handoff is state:
                        current_session=read_session()
                        if current_session is None or current_session.get("state_handoff")!=handoff:
                            release_recovery_reservation(); print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                        try: _require_owner_baseline(current_session)
                        except ValueError:
                            release_recovery_reservation(); raise
                        session=current_session; state=session["state_handoff"]; handoff=state
                        changed=not _pending_state_matches_worktree(handoff)
                    else:
                        current,item,_directory,tasks=_current_session_scope()
                        if current.get("commit_handoff")!=handoff:
                            release_recovery_reservation(); print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                        _task,blocked=_commit_readiness(current,item,tasks,handoff["task"])
                        current_paths,current_tree,paths_blocked=_review_candidate(current,item)
                        changed=bool(blocked or paths_blocked or current_tree!=tree or current_paths!=recovery_content_paths or not _pending_commit_matches_worktree(handoff,current_paths))
                    if changed or not prepared_index_matches_tree(lock,tree,handoff["prepared_index_digest"]):
                        release_recovery_reservation()
                        print("BLOCK_CANDIDATE_CHANGED_DURING_RECOVERY" if handoff is not state else "BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                    if handoff is state and handoff.get("operation") in {"activate-successor","complete-request"} and "review_retirement_digest" in handoff:
                        refreshed,blocked=_recovery_retirement_revalidation(handoff)
                        if blocked:
                            release_recovery_reservation()
                            print(blocked); return 65
                        if not isinstance(refreshed,dict) or not isinstance(refreshed.get("state_handoff"),dict):
                            release_recovery_reservation(); print("BLOCK_REVIEW_RETIREMENT_STATE_CHANGED"); return 65
                        session=refreshed; state=session["state_handoff"]; handoff=state
                        if not _pending_state_matches_worktree(handoff):
                            release_recovery_reservation(); print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                    if handoff is state:
                        final_session=read_session()
                        if final_session is None or final_session.get("state_handoff")!=handoff:
                            release_recovery_reservation(); print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                        try: _require_owner_baseline(final_session)
                        except ValueError:
                            release_recovery_reservation(); raise
                        final_state=final_session["state_handoff"]
                        if not _pending_state_matches_worktree(final_state) or not prepared_index_matches_tree(lock,tree,final_state["prepared_index_digest"]):
                            release_recovery_reservation(); print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                        if final_state.get("operation")=="resolve-review" and not _review_state_binding_matches(final_session,final_state):
                            release_recovery_reservation(); print("BLOCK_REVIEW_STATE_CHANGED"); return 65
                        session=final_session; state=final_state; handoff=final_state
                    else:
                        final_session,item,_directory,tasks=_current_session_scope()
                        if final_session.get("commit_handoff")!=handoff:
                            release_recovery_reservation(); print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                        _task,blocked=_commit_readiness(final_session,item,tasks,handoff["task"])
                        final_paths,final_tree,paths_blocked=_review_candidate(final_session,item)
                        if blocked or paths_blocked or final_tree!=tree or final_paths!=recovery_content_paths or not _pending_commit_matches_worktree(handoff,final_paths) or not prepared_index_matches_tree(lock,tree,handoff["prepared_index_digest"]):
                            release_recovery_reservation(); print("BLOCK_CANDIDATE_CHANGED_DURING_RECOVERY"); return 65
                        session=final_session; handoff=session["commit_handoff"]
                        if required_review_stages(item):
                            _publish_commit_evidence_origin(session,item,expected,tree,parent)
                            final_session=read_session()
                            if final_session is None or final_session.get("commit_handoff")!=handoff:
                                release_recovery_reservation(); print("BLOCK_STATE_CANDIDATE_CHANGED"); return 65
                            try: _require_owner_baseline(final_session)
                            except ValueError:
                                release_recovery_reservation(); raise
                            final_item=current_feature(); final_tasks=_task_scope_from_directory(final_item,final_item["spec_directory"])[1]
                            _task,blocked=_commit_readiness(final_session,final_item,final_tasks,handoff["task"])
                            if blocked or not _pending_commit_matches_worktree(handoff,recovery_content_paths) or not prepared_index_matches_tree(lock,tree,handoff["prepared_index_digest"]):
                                release_recovery_reservation(); print(blocked or "BLOCK_CANDIDATE_CHANGED_DURING_RECOVERY"); return 65
                            session=final_session; item=final_item; handoff=session["commit_handoff"]
                    if handoff is state and handoff.get("operation") in {"activate-successor","complete-request"}:
                        source_error=_generated_origin_evidence_error(payloads,handoff["operation"])
                        if source_error:
                            release_recovery_reservation(); print(source_error); return 65
                    try: git("update-ref","HEAD",expected,parent); head=expected
                    except ValueError:
                        release_recovery_reservation(); raise
                if head!=expected: release_recovery_reservation(); print("BLOCK_PREPARED_HEAD_CHANGED"); return 65
                if not finalize_prepared_index_reservation(lock,descriptor,identity,tree,handoff["prepared_index_digest"]): print("BLOCK_PREPARED_INDEX_RECOVERY_REQUIRED"); return 65
                handoff["state"]="committed"; handoff["committed_head"]=expected
                if handoff is state:
                    session["state_handoff"]=handoff; publish_session(session,replace=True)
                    decision,blocked=_resume_state_handoff(session,handoff)
                    if blocked: print(blocked); return 65
                    print(json.dumps({"schema":1,"decision":decision,"committed_head":expected,"next_feature":handoff["next_feature"]},sort_keys=True)); return 0
                session["commit_handoff"]=handoff; publish_session(session,replace=True)
                blocked=_record_midtask_content(session)
                if blocked: print(blocked); return 65
                print(json.dumps({"schema":1,"decision":"RECOVERED_LOCAL_COMMIT","committed_head":expected,"next_feature":handoff["next_feature"]},sort_keys=True)); return 0
    except ValueError as exc: print(str(exc),file=sys.stderr); return 65


def next_eligible_feature(document: dict[str, Any], current_id: str, *, completing_current: bool = False) -> str | None:
    states={item.get("id"):item.get("status") for item in document.get("features",[]) if isinstance(item,dict)}
    if completing_current:
        states[current_id]="passing"
    candidates=[]
    for item in document.get("features",[]):
        if not isinstance(item,dict) or item.get("status")!="not_started" or item.get("id")==current_id: continue
        if all(states.get(dependency)=="passing" for dependency in item.get("depends_on",[])):
            candidates.append(item)
    candidates.sort(key=lambda item:(item.get("priority",999),item.get("id","")))
    return candidates[0].get("id") if candidates else None


def checkpoint(args: list[str]) -> int:
    if len(args)!=2 or args[0]!="--task" or not re.fullmatch(r"T[0-9]{3}",args[1]):
        print("Usage: bin/agent-session checkpoint --task Txxx",file=sys.stderr); return 64
    try: session=read_session()
    except ValueError as exc: print(str(exc),file=sys.stderr); return 65
    if session is None: print("run bin/agent-session start first",file=sys.stderr); return 65
    if session_review_readiness_errors(session): print("BLOCK_UNRESOLVED_MATERIAL_REVIEW",file=sys.stderr); return 65
    item=current_feature();
    if session.get("work_item")!=item.get("id"): print("session scope is stale; restart the session after reviewing current feature state",file=sys.stderr); return 65
    directory,tasks=_active_task_scope(item)
    if session.get("task_directory")!=directory or session.get("task_ids")!=[entry["id"] for entry in tasks]:
        print("session task scope is stale; restart the session after reviewing the active task ledger",file=sys.stderr); return 65
    task=next((entry for entry in tasks if entry["id"]==args[1]),None)
    if task is None: print(f"task {args[1]} is not declared by the active feature",file=sys.stderr); return 65
    if not task["complete"]: print(f"task {args[1]} is not complete; checkpoint is read-only and cannot mark it complete",file=sys.stderr); return 65
    if session.get("request_ref") is not None:
        try:
            decision=_shared_request_decision(session,item,tasks,task["id"])
        except ValueError as exc:
            print(str(exc),file=sys.stderr); return 65
        assert decision is not None
        result={"schema":1,"feature":item["id"],"execution_mode":session["execution_mode"],"feature_limit":session["feature_limit"],"completed_features":session["completed_features"],"checkpointed_task":task["id"],"next_task":decision["task"] if decision["decision"]=="BUILD_TASK" else None,"next_feature":decision["feature"] if decision["decision"]=="ADVANCE_REQUIRED" else None,"decision":decision["checkpoint_decision"] or decision["decision"],"handoff_required":decision["handoff_required"],"request_decision":decision["decision"],"reason":decision["reason"]}
        print(json.dumps(result,indent=2,sort_keys=True)); return 0
    mode=session["execution_mode"]; incomplete=[entry["id"] for entry in tasks if not entry["complete"]]
    result={"schema":1,"feature":item["id"],"execution_mode":mode,"feature_limit":session["feature_limit"],"completed_features":session["completed_features"],"checkpointed_task":task["id"],"next_task":incomplete[0] if incomplete else None,"next_feature":None,"decision":None,"handoff_required":None}
    if mode=="task":
        result["decision"]="STOP_AFTER_TASK"
    elif incomplete:
        result["decision"]="CONTINUE_FEATURES" if mode=="features" else ("CONTINUE_REQUEST" if mode=="request" else "CONTINUE_FEATURE")
    elif mode=="feature":
        result["decision"]="STOP_AFTER_FEATURE"
    elif mode=="request":
        if not session.get("follow_on"):
            # A legacy request with no explicitly requested tail has no
            # authority to scan the global backlog.  It stops here rather
            # than selecting an arbitrary eligible feature.
            result["decision"]="STOP_AFTER_REQUEST"
            print(json.dumps(result,indent=2,sort_keys=True)); return 0
        # Legacy sessions have no durable request artifact.  Use the same
        # selector only for this read-only queue preview; commit/advance still
        # require their existing guarded transaction checks and receive no
        # optional, report, or event authority from this synthetic contract.
        decision=_legacy_queue_decision(session,item,tasks)
        result["request_decision"]=decision["decision"]
        result["reason"]=decision["reason"]
        if decision["decision"]=="BUILD_TASK":
            result["decision"]="CONTINUE_REQUEST"; result["next_task"]=decision["task"]
        elif decision["decision"]=="ADVANCE_REQUIRED":
            result["decision"]="CONTINUE_REQUEST"; result["next_feature"]=decision["feature"]; result["handoff_required"]="commit-bound-baseline-before-next-feature"
        elif decision["decision"]=="COMPLETE":
            result["decision"]="STOP_AFTER_REQUEST"
        else:
            result["decision"]="STOP_REQUEST_BLOCKED"; result["handoff_required"]=decision["reason"]
    elif session["completed_features"]+1>=session["feature_limit"]:
        result["decision"]="STOP_AFTER_FEATURE_LIMIT"
    else:
        result["next_feature"]=next_eligible_feature(feature_document(),item["id"],completing_current=True)
        if result["next_feature"] is None: result["decision"]="STOP_NO_ELIGIBLE_FEATURE"
        else:
            result["decision"]="CONTINUE_FEATURES"
            result["handoff_required"]="commit-bound-baseline-before-next-feature"
    print(json.dumps(result,indent=2,sort_keys=True)); return 0


def intent(args: list[str]) -> int:
    if len(args)!=2 or args[0]!="--prompt":
        print("Usage: bin/agent-session intent --prompt TEXT",file=sys.stderr); return 64
    try:
        print(json.dumps(continuation_intent(args[1]),indent=2,sort_keys=True)); return 0
    except ValueError as exc:
        print(str(exc),file=sys.stderr); return 65


def policy_view(args: list[str]) -> int:
    if args: print("Usage: bin/agent-session policy",file=sys.stderr); return 64
    try:
        session=read_session(); effective=session.get("continuation_policy") if session is not None else continuation_policy()
        print(json.dumps({"schema":1,"effective_policy":effective,"session_bound":session is not None},sort_keys=True)); return 0
    except ValueError as exc: print(str(exc),file=sys.stderr); return 65


def _verify_profiles(names: list[str]) -> int:
    if not names: print("Usage: bin/agent-session verify <profile>...",file=sys.stderr); return 64
    cfg=project()
    if project_contract_errors(cfg):
        print("verification project contract is invalid",file=sys.stderr); return 65
    session=read_session()
    if session is None: print("run bin/agent-session start first",file=sys.stderr); return 65
    item=current_feature()
    if session.get("work_item") != item["id"] or session.get("profiles") != item["required_profiles"]:
        print("session scope is stale; restart the session after reviewing current feature state",file=sys.stderr); return 65
    if not session_task_scope_matches(session,item):
        print("session task scope is stale; restart the session after reviewing the active task ledger",file=sys.stderr); return 65
    if session.get("continuation_policy",{}).get("review")=="agent":
        _preflight,preflight_errors=review_preflight(session,item)
        if preflight_errors:
            print("\n".join(preflight_errors),file=sys.stderr); return 65
        _directory,tasks=_active_task_scope(item)
        if not tasks:
            print("BLOCK_PREVERIFICATION_REVIEW_REQUIRED\nBLOCK_INCOMPLETE_TASK",file=sys.stderr); return 65
        outcomes=session.get("review_outcomes",[])
        reviewed_task=(outcomes[0].get("task") if outcomes and isinstance(outcomes[0],dict) else None)
        if not isinstance(reviewed_task,str) or not any(task["id"]==reviewed_task for task in tasks):
            completed=[task["id"] for task in tasks if task["complete"]]
            reviewed_task=completed[-1] if completed else tasks[0]["id"]
        _reviewed,review_error=_precommit_review_readiness(session,item,tasks,reviewed_task)
        if review_error is not None:
            print("BLOCK_PREVERIFICATION_REVIEW_REQUIRED\n"+review_error,file=sys.stderr); return 65
    for name in names:
        if name not in item["required_profiles"]: print(f"profile {name} is not declared by {item['id']}",file=sys.stderr); return 65
        definition=cfg["profiles"].get(name)
        if not definition: print(f"unknown profile {name}",file=sys.stderr); return 65
        if not definition["commands"]: print(f"profile {name} unavailable: {definition.get('unavailable')}",file=sys.stderr); return 69
        source_binding=_verification_source_binding(session,item)
        before_identity,before=receipt_namespace_snapshot(session.get("receipt_key",""),allow_stale_bindings=True,session=session); validate_transaction_identity()
        reusable=next((entry[2] for _filename,entry in sorted(before.items(),reverse=True) if entry[1]==name),None)
        if isinstance(reusable,dict) and reusable.get("schema")==2 and reusable.get("exit_status")==0 and reusable.get("candidate_binding")==source_binding:
            print(f"receipt reused: {name}; active candidate binding is unchanged")
            continue
        started=dt.datetime.now(dt.timezone.utc).isoformat(timespec="microseconds").replace("+00:00","Z")
        total_ms=0; out=hashlib.sha256(); err=hashlib.sha256(); status=0; checks=[]
        for index,argv in enumerate(definition["commands"],1):
            status,od,ed,duration=run_argv(argv,aggregate_out=out,aggregate_err=err); total_ms+=duration
            checks.append({"check_id":f"{name}:{index}","command_digest":hashlib.sha256(json.dumps(argv,separators=(",",":")).encode()).hexdigest(),"duration_ms":duration,"exit_status":status,"stdout_digest":od,"stderr_digest":ed})
            if status: break
        receipt={"schema":2,"profile":name,"layer":definition["layer"],"command_digest":hashlib.sha256(json.dumps(definition["commands"],separators=(",",":")).encode()).hexdigest(),"started_at":started,"duration_ms":total_ms,"exit_status":status,"work_item":item["id"],"surface_digest":surface_digest(item),"profile_digest":profile_digest(item),"requirement_digest":requirement_digest(item),"stdout_digest":out.hexdigest(),"stderr_digest":err.hexdigest(),"checks":checks,"candidate_binding":source_binding}
        receipt["signature"] = receipt_signature(receipt, session.get("receipt_key", ""))
        assert set(receipt)==RECEIPT_KEYS
        serialized=json.dumps(receipt,sort_keys=True)
        if FORBIDDEN_RECEIPT.search(serialized): print("receipt privacy policy rejected metadata",file=sys.stderr); return 70
        if _verification_source_binding(read_session(),current_feature())!=source_binding:
            raise ValueError("verification source changed while profile ran")
        middle_identity,middle=receipt_namespace_snapshot(session.get("receipt_key",""),allow_stale_bindings=True,session=session)
        if middle_identity!=before_identity or middle!=before: raise ValueError("receipt namespace changed while verification ran")
        validate_transaction_identity(); namespace=receipt_namespace(session); directory_fd=open_admin_directory("repository-agent-session",namespace,create=True)
        try:
            directory_metadata=os.fstat(directory_fd); directory_identity=(directory_metadata.st_dev,directory_metadata.st_ino)
            if middle_identity is not None and middle_identity!=directory_identity: raise ValueError("receipt namespace changed before publication")
            filename=re.sub(r"[-:]","",started).replace(".",".")+f"-{name}.json"
            published_identity=_publish_bytes(directory_fd,filename,(json.dumps(receipt,indent=2)+"\n").encode())
        finally:
            os.close(directory_fd)
        try:
            after_identity,after=receipt_namespace_snapshot(session.get("receipt_key",""),allow_stale_bindings=True,session=session)
            if after_identity!=directory_identity or set(after)!=set(before)|{filename} or any(after[key][0]!=value[0] for key,value in before.items()) or after[filename][0][:2]!=published_identity: raise ValueError("receipt namespace changed during publication")
            validate_transaction_identity()
        except ValueError:
            _remove_owned_publication(namespace,filename,directory_identity,published_identity)
            raise
        print(f"receipt recorded: {filename}")
        if status: return status
    return 0


def verify_profiles(names: list[str]) -> int:
    try:
        with admin_transaction(): return _verify_profiles(names)
    except ValueError as exc:
        print(str(exc),file=sys.stderr); return 65


def _verification_source_binding(session: dict[str,Any] | None, item: dict[str,Any]) -> str:
    """Digest every governed input and authority binding around a profile run."""
    if not isinstance(session,dict): raise ValueError("verification session changed while profile ran")
    request= session.get("request_ref")
    binding={
        "session_started_at":session.get("started_at"),
        "base_head":session.get("base_head"),
        "surface":surface_digest(item),
        "profiles":profile_digest(item),
        "requirements":requirement_digest(item),
        "tasks":session.get("task_ids"),
        "task_directory":session.get("task_directory"),
        "task_digest":hashlib.sha256((ROOT/session["task_directory"]/"tasks.md").read_bytes()).hexdigest() if isinstance(session.get("task_directory"),str) and (ROOT/session["task_directory"]/"tasks.md").is_file() else None,
        "design_documents":_selected_design_document_digests(session,item),
        "scope":continuation_scope_digest(session),
        "policy":execution_policy_digest(),
        "request":request,
    }
    return hashlib.sha256(json.dumps(binding,sort_keys=True,separators=(",",":")).encode()).hexdigest()


def _selected_design_document_digests(session: dict[str,Any], item: dict[str,Any]) -> dict[str,str|None]:
    """Bind selected design bytes even when repository-local Git excludes them."""
    selected=session.get("task_directory") or item.get("spec_directory")
    return _design_document_digests(selected)


def _design_document_digests(selected: Any) -> dict[str,str|None]:
    """Use one canonical, no-follow design binding for receipts and reviews."""
    if selected is None:
        return {"spec.md":None,"plan.md":None,"tasks.md":None}
    directory=canonical_spec_directory(selected)
    if directory is None:
        raise ValueError("BLOCK_UNSAFE_SELECTED_DESIGN_DIRECTORY")
    try:
        directory_fd=open_repo_directory(*Path(directory).parts)
    except ValueError as exc:
        raise ValueError("BLOCK_UNSAFE_SELECTED_DESIGN_DIRECTORY") from exc
    try:
        result: dict[str,str|None]={}
        for name in ("spec.md","plan.md","tasks.md"):
            try:
                payload=_read_regular_nofollow(directory_fd,name,f"selected {name}")
            except FileNotFoundError:
                result[name]=None
            except ValueError as exc:
                if str(exc).startswith("unsafe selected "):
                    # A missing selected document is represented explicitly;
                    # symlinks, non-files, and oversized files stay blocked.
                    try:
                        os.stat(name,dir_fd=directory_fd,follow_symlinks=False)
                    except FileNotFoundError:
                        result[name]=None
                    else:
                        raise ValueError(f"BLOCK_UNSAFE_SELECTED_DESIGN_DOCUMENT:{name}") from exc
                else:
                    raise
            else:
                result[name]=hashlib.sha256(payload).hexdigest()
        return result
    finally:
        os.close(directory_fd)


def receipt_namespace_snapshot(receipt_key: str, *, allow_stale_bindings: bool = False, session: dict[str,Any] | None = None) -> tuple[tuple[int,int] | None,dict[str,tuple[tuple[Any,...],str,dict[str,Any]]]]:
    namespace=receipt_namespace(session)
    try: directory_fd=open_admin_directory("repository-agent-session",namespace)
    except ValueError:
        if os.path.lexists(git_dir()/namespace): raise
        return (None,{})
    retained={}
    try:
        names=sorted(os.listdir(directory_fd))
        for name in names:
            if name=="decisions.json":
                descriptor=None
                try:
                    descriptor=os.open(name,os.O_RDONLY|getattr(os,"O_NOFOLLOW",0)|getattr(os,"O_NONBLOCK",0),dir_fd=directory_fd); metadata=os.fstat(descriptor)
                    if not stat.S_ISREG(metadata.st_mode) or stat.S_IMODE(metadata.st_mode)!=0o600: raise ValueError("decision records are unsafe")
                    data=os.read(descriptor,1_000_001)
                    if len(data)>1_000_000: raise ValueError("decision records are oversized")
                    errors=decision_record_errors(json.loads(data.decode("utf-8")),receipt_key)
                    if errors: raise ValueError("; ".join(errors))
                finally:
                    if descriptor is not None: os.close(descriptor)
                continue
            matched=re.fullmatch(r"\d{8}T\d{6}\.\d{6}Z-([a-z][a-z0-9-]*)\.json",name)
            if not matched: raise ValueError("receipt namespace contains a noncanonical entry")
            candidate_profile=matched.group(1); descriptor=None
            try:
                descriptor=os.open(name,os.O_RDONLY|getattr(os,"O_NOFOLLOW",0)|getattr(os,"O_NONBLOCK",0),dir_fd=directory_fd); metadata=os.fstat(descriptor)
                if not stat.S_ISREG(metadata.st_mode) or stat.S_IMODE(metadata.st_mode)!=0o600: raise ValueError("receipt namespace contains an unsafe entry")
                data=b""
                while True:
                    chunk=os.read(descriptor,65536)
                    if not chunk: break
                    data+=chunk
                    if len(data)>1_000_000: raise ValueError("receipt is oversized")
                value=json.loads(data.decode("utf-8"))
                if not receipt_semantically_valid(value,candidate_profile,name,receipt_key,allow_stale_bindings=allow_stale_bindings,session=session): raise ValueError("receipt namespace contains invalid evidence")
                token=(metadata.st_dev,metadata.st_ino,stat.S_IMODE(metadata.st_mode),metadata.st_nlink,metadata.st_size,metadata.st_mtime_ns,metadata.st_ctime_ns,hashlib.sha256(data).hexdigest())
                retained[name]=(token,candidate_profile,value)
            except (OSError,TypeError,json.JSONDecodeError,UnicodeError) as exc: raise ValueError("receipt namespace contains invalid evidence") from exc
            finally:
                if descriptor is not None:
                    try: os.close(descriptor)
                    except OSError: pass
        if sorted(os.listdir(directory_fd))!=names: raise ValueError("receipt namespace changed during validation")
        for name,(token,_profile,_value) in retained.items():
            reopened=os.open(name,os.O_RDONLY|getattr(os,"O_NOFOLLOW",0)|getattr(os,"O_NONBLOCK",0),dir_fd=directory_fd)
            try:
                metadata=os.fstat(reopened); current=(metadata.st_dev,metadata.st_ino,stat.S_IMODE(metadata.st_mode),metadata.st_nlink,metadata.st_size,metadata.st_mtime_ns,metadata.st_ctime_ns)
                if current!=token[:7]: raise ValueError("receipt namespace entry changed during validation")
            finally: os.close(reopened)
        metadata=os.fstat(directory_fd); original_identity=(metadata.st_dev,metadata.st_ino)
        reopened_directory=open_admin_directory("repository-agent-session",namespace)
        try:
            current=os.fstat(reopened_directory)
            if (current.st_dev,current.st_ino)!=original_identity: raise ValueError("receipt namespace changed during validation")
        finally: os.close(reopened_directory)
        validate_transaction_identity(); return (original_identity,retained)
    finally: os.close(directory_fd)


def latest_receipt(profile: str, receipt_key: str, *, allow_stale_bindings: bool = False) -> dict[str, Any] | None:
    _identity,retained=receipt_namespace_snapshot(receipt_key,allow_stale_bindings=allow_stale_bindings)
    for name in sorted(retained,reverse=True):
        _token,candidate_profile,value=retained[name]
        if candidate_profile==profile: return value
    return None


def matches_expected(path: str,item: dict[str,Any]) -> bool:
    return any(fnmatch.fnmatch(path,pattern) or fnmatch.fnmatch(path,pattern.rstrip("/**")) for pattern in item["expected_paths"])


def _finish() -> int:
    session=read_session()
    if session is None: print("VERDICT: NOT_CLEAN\nrun bin/agent-session start first",file=sys.stderr); return 65
    local_journal=_local_transition_read()
    if isinstance(local_journal,dict) and local_journal.get("state")=="pending":
        print("VERDICT: NOT_CLEAN\nlocal state transition is pending; run bin/agent-session recover-commit",file=sys.stderr); return 65
    _require_owner_baseline(session)
    review_errors=session_review_readiness_errors(session)
    if review_errors: print("VERDICT: BLOCKED\n"+"\n".join(review_errors)); return 65
    try: item=current_feature()
    except ValueError:
        if session.get("request_ref") is None:
            document=feature_document()
            active=[entry for entry in document.get("features",[]) if isinstance(entry,dict) and entry.get("status")=="in_progress"]
            if active:
                print("VERDICT: NOT_CLEAN\nexpected at most one active feature for a terminal queue",file=sys.stderr); return 65
            terminal_statuses={"passing","superseded","paused","suspended","archived"}
            unfinished=[entry for entry in document.get("features",[]) if not isinstance(entry,dict) or entry.get("status") not in terminal_statuses]
            if unfinished:
                identifiers=", ".join(f"{entry.get('id','unknown')} ({entry.get('status','unknown')})" for entry in unfinished if isinstance(entry,dict))
                print("VERDICT: NOT_CLEAN\nunfinished work remains: "+identifiers+"; activate or unblock eligible work before finishing")
                return 65
            ledger_issues=validation_errors(document,project(),allow_terminal_queue=True)
            if ledger_issues:
                print("VERDICT: NOT_CLEAN\nterminal feature ledger is invalid: "+"; ".join(ledger_issues),file=sys.stderr); return 65
            if status_entries():
                print("VERDICT: NOT_CLEAN\nrepository changes remain at terminal finish",file=sys.stderr); return 65
            print("VERDICT: CLEAN_HANDOFF")
            return 0
        try:
            request,reference=read_bound_request(document=feature_document())
        except ValueError as exc:
            print(f"VERDICT: NOT_CLEAN\n{exc}",file=sys.stderr); return 65
        if reference!=session.get("request_ref") or _terminal_request_pair_errors(request,feature_document(),reference=reference):
            print("VERDICT: NOT_CLEAN\nterminal request state is invalid",file=sys.stderr); return 65
        if status_entries():
            print("VERDICT: ATTRIBUTED_DIRTY_HANDOFF"); return 0
        print("VERDICT: CLEAN_HANDOFF")
        return 0
    if not session_task_scope_matches(session,item):
        print("VERDICT: NOT_CLEAN\nsession task scope is stale; restart the session after reviewing the active task ledger",file=sys.stderr); return 65
    issues=[]
    baseline={x["path"]:x for x in session.get("baseline",[])}; current={x["path"]:x for x in status_entries()}
    attributed=bool(current)
    for name in sorted(set(baseline)|set(current)):
        if matches_expected(name,item): continue
        if name in baseline and name in current and baseline[name]==current[name]: continue
        if name in baseline: issues.append(f"baseline drifted: {name}")
        else: issues.append(f"unexplained path: {name}")
    expected_surface=surface_digest(item); expected_profile=profile_digest(item); expected_requirement=requirement_digest(item); effective_receipts=None
    state=session.get("state_handoff"); handoff=session.get("commit_handoff")
    if isinstance(state,dict) and state.get("operation")=="resolve-review" and state.get("state")=="committed" and isinstance(handoff,dict):
        try:
            resolved=_origin_receipts(handoff.get("committed_head",""),state.get("committed_head",""),item)
            if resolved is not None: effective_receipts=resolved[1]
        except ValueError as exc: issues.append(str(exc))
    for name in item["required_profiles"]:
        try: receipt=effective_receipts.get(name) if effective_receipts is not None else latest_receipt(name,session.get("receipt_key", ""),allow_stale_bindings=True)
        except ValueError: issues.append(f"invalid evidence namespace: {name}"); continue
        if not receipt: issues.append(f"missing evidence: {name}"); continue
        if receipt.get("exit_status")!=0: issues.append(f"failing evidence: {name}")
        if receipt.get("work_item")!=item["id"] or receipt.get("profile_digest")!=expected_profile or (effective_receipts is None and (receipt.get("surface_digest")!=expected_surface or receipt.get("requirement_digest")!=expected_requirement)):
            issues.append(f"stale evidence: {name}")
        if effective_receipts is None and receipt.get("candidate_binding")!=_verification_source_binding(session,item):
            issues.append(f"stale candidate receipt: {name}")
    if not item.get("next_action","").strip(): issues.append("next action is empty")
    if "independent-review" not in item.get("external_gates",[]) and required_review_stages(item):
        review_block=_required_review_resolution_error(session,item)
        if review_block: issues.append(review_block)
    if issues:
        print("VERDICT: NOT_CLEAN")
        for issue in issues: print("- "+issue)
        return 65
    if session.get("base_head")=="UNBORN":
        verdict="UNBASELINED_HANDOFF_WITH_EXTERNAL_GATES" if item["external_gates"] else "UNBASELINED_HANDOFF"
        print("VERDICT: "+verdict); print("a durable source baseline is required before acceptance"); return 65
    effective_external_gates=item["external_gates"]
    handoff=session.get("commit_handoff")
    if "independent-review" in effective_external_gates and isinstance(handoff,dict):
        resolved,_blocked=_review_resolution_ready(session,item,handoff)
        if resolved is not None:
            effective_external_gates=[gate for gate in effective_external_gates if gate!="independent-review"]
    if item["status"]=="blocked": verdict="BLOCKED"
    elif attributed and effective_external_gates: verdict="ATTRIBUTED_DIRTY_HANDOFF_WITH_EXTERNAL_GATES"
    elif attributed: verdict="ATTRIBUTED_DIRTY_HANDOFF"
    elif effective_external_gates: verdict="CLEAN_HANDOFF_WITH_EXTERNAL_GATES"
    else: verdict="CLEAN_HANDOFF"
    print("VERDICT: "+verdict)
    if effective_external_gates: print("open external gates: "+", ".join(effective_external_gates))
    return 0


def _mark_passing(next_id: str | None = None, next_spec_directory: str | None = None, *, deferred_payloads: bool = False) -> int | dict[str, bytes]:
    if worker_assignment() is not None:
        print("batch workers cannot publish passing; hand the candidate to the integration coordinator", file=sys.stderr); return 65
    errors=validation_errors()+docs_errors()
    if errors: print("\n".join(errors),file=sys.stderr); return 65
    item=current_feature(); session=read_session()
    if session is None: print("start and verify a session before marking passing",file=sys.stderr); return 65
    readiness_errors=session_review_readiness_errors(session)
    if readiness_errors:
        print("BLOCK_UNRESOLVED_MATERIAL_REVIEW",file=sys.stderr); return 65
    if not session_task_scope_matches(session,item): print("session task scope is stale; restart the session before marking passing",file=sys.stderr); return 65
    if item["external_gates"]: print("cannot mark passing while external gates remain open",file=sys.stderr); return 65
    review_block=_required_review_resolution_error(session,item)
    if review_block: print(review_block,file=sys.stderr); return 65
    head=git("rev-parse","HEAD",check=False).decode().strip()
    if not re.fullmatch(r"[0-9a-f]{40}",head) or session.get("base_head")!=head:
        print("passing requires a committed source baseline matching the active session",file=sys.stderr); return 65
    if session.get("mode")!="require-pristine" or session.get("baseline") or status_entries():
        print("passing requires a pristine committed source baseline",file=sys.stderr); return 65
    key=session.get("receipt_key",""); evidence=[]; attestations=[]; local_binding=_installed_local_state_binding()
    state=session.get("state_handoff"); handoff=session.get("commit_handoff"); reused=None
    local_review_digest=None
    if local_binding is not None:
        try: review_bytes=_local_transition_file_bytes(_domain_path(f"harness/reviews/{handoff['committed_head']}.json"))
        except (OSError,ValueError,KeyError): review_bytes=None
        if review_bytes is None: print("installed local feature completion requires its durable review record",file=sys.stderr); return 65
        local_review_digest=hashlib.sha256(review_bytes).hexdigest()
    if isinstance(state,dict) and state.get("operation")=="resolve-review" and state.get("state")=="committed" and isinstance(handoff,dict):
        try: reused=_origin_receipts(handoff.get("committed_head",""),head,item)
        except ValueError as exc: print(str(exc),file=sys.stderr); return 65
    if local_binding is not None:
        try: reused=_local_origin_receipts(session,item)
        except ValueError as exc: print(str(exc),file=sys.stderr); return 65
    for profile in item["required_profiles"]:
        receipt=reused[1].get(profile) if reused is not None else latest_receipt(profile,key,allow_stale_bindings=True)
        if receipt is None or receipt.get("exit_status")!=0 or receipt.get("work_item")!=item["id"]:
            print(f"missing current successful receipt for {profile}",file=sys.stderr); return 65
        if reused is None and receipt.get("schema")==2 and receipt.get("candidate_binding")!=_verification_source_binding(session,item):
            print(f"receipt is not bound to the current candidate for {profile}",file=sys.stderr); return 65
        receipt_digest=hashlib.sha256(json.dumps(receipt,sort_keys=True,separators=(",",":")).encode()).hexdigest()
        domain_fields={"state_domain":STATE_DOMAIN,"ledger_path":state_domains.owner(STATE_DOMAIN,"feature_list.json")}
        if local_binding is not None:
            source=handoff["committed_head"]
            evidence.append({"schema":4,"profile":profile,"command_digest":receipt["command_digest"],"surface_digest":receipt["surface_digest"],"profile_digest":receipt["profile_digest"],"requirement_digest":receipt["requirement_digest"],"receipt_digest":receipt_digest,"verified_at":receipt["started_at"],"source_commit":source,**domain_fields,"local_review_digest":local_review_digest,"distribution":local_binding["distribution"],"exclude_digest":local_binding["exclude_digest"]})
            attestations.append((receipt_digest,{"schema":4,"source_commit":source,"work_item":item["id"],"profile":profile,"receipt":receipt,**domain_fields,"local_review_digest":local_review_digest,"distribution":local_binding["distribution"],"exclude_digest":local_binding["exclude_digest"]}))
        elif reused is not None:
            source=reused[0]["source_commit"]
            evidence.append({"schema":3,"profile":profile,"command_digest":receipt["command_digest"],"surface_digest":receipt["surface_digest"],"profile_digest":receipt["profile_digest"],"requirement_digest":receipt["requirement_digest"],"receipt_digest":receipt_digest,"verified_at":receipt["started_at"],"source_commit":source,"resolution_commit":head,**domain_fields})
            attestations.append((receipt_digest,{"schema":3,"source_commit":source,"resolution_commit":head,"work_item":item["id"],"profile":profile,"receipt":receipt,**domain_fields}))
        else:
            evidence.append({"schema":3,"profile":profile,"command_digest":receipt["command_digest"],"surface_digest":receipt["surface_digest"],"profile_digest":receipt["profile_digest"],"requirement_digest":receipt["requirement_digest"],"receipt_digest":receipt_digest,"verified_at":receipt["started_at"],"source_commit":head,"resolution_commit":None,**domain_fields})
            attestations.append((receipt_digest,{"schema":3,"source_commit":head,"resolution_commit":None,"work_item":item["id"],"profile":profile,"receipt":receipt,**domain_fields}))
    # Verification may take a long time. Check the independent owner authority
    # at the point where passing evidence is about to be published.
    _require_owner_baseline(session)
    document=feature_document(); targets=[candidate for candidate in document["features"] if candidate.get("id")==item["id"]]
    if len(targets)!=1: print("active feature identity changed",file=sys.stderr); return 65
    targets[0]["status"]="passing"; targets[0]["evidence"]=evidence; targets[0]["next_action"]="Retain this immutable attestation and activate the next bounded feature, if any."
    if next_id is not None:
        successors=[candidate for candidate in document["features"] if candidate.get("id")==next_id]
        if len(successors)!=1:
            print(f"cannot activate unknown next feature {next_id}",file=sys.stderr); return 65
        successor=successors[0]
        if successor.get("status")!="not_started":
            print(f"next feature {next_id} must be not_started",file=sys.stderr); return 65
        states={candidate.get("id"):candidate.get("status") for candidate in document["features"]}
        unmet=[dependency for dependency in successor.get("depends_on",[]) if states.get(dependency)!="passing"]
        if unmet:
            print(f"next feature {next_id} has unmet dependencies: {', '.join(unmet)}",file=sys.stderr); return 65
        # The guarded continuation path supplies its already-pinned directory.
        # Preserve the public mark-passing command's legacy selector by deriving
        # its declared directory before the shared document validation below.
        if next_spec_directory is None and deferred_payloads:
            print("next feature requires a pinned safe spec directory",file=sys.stderr); return 65
        if next_spec_directory is None:
            next_spec_directory=successor.get("spec_directory")
        successor["status"]="in_progress"
    elif session.get("request_ref") is None:
        if any(candidate.get("status") in {"not_started","blocked"} for candidate in document["features"]):
            print("unfinished work remains; rerun with --activate-next FEATURE_ID to select the next bounded feature",file=sys.stderr); return 65
    elif any(candidate.get("status") not in {"passing","superseded"} for candidate in document["features"]):
        request,_reference=read_bound_request(document=document); members={*request["contract"]["required"],*(entry["feature"] for entry in request["contract"]["optional"])}
        if not deferred_payloads and any(candidate.get("id") in members and candidate.get("status") not in {"passing","superseded"} for candidate in document["features"]):
            print("unfinished requested work remains",file=sys.stderr); return 65
    expected_pending_evidence=f"passing feature {item['id']} has invalid durable evidence"
    intrinsic_terminal=deferred_payloads and next_id is None and session.get("request_ref") is not None
    if intrinsic_terminal:
        # A terminal request is paired with its generated journal only by the
        # private transaction below.  The public ledger validator correctly
        # refuses this intentionally incomplete half while it is unpublished.
        post_errors=[]
    else:
        post_errors=[error for error in validation_errors(document,project(),active_spec_directory=next_spec_directory) if error!=expected_pending_evidence]
    if post_errors: print("\n".join(post_errors),file=sys.stderr); return 65
    if next_id is not None:
        if canonical_spec_directory(next_spec_directory) is None:
            print("next feature requires a pinned safe spec directory",file=sys.stderr); return 65
        try: _task_scope_from_directory(successor,next_spec_directory)
        except ValueError as exc: print(str(exc),file=sys.stderr); return 65
    ledger_payload=(json.dumps(document,indent=2)+"\n").encode()
    if local_binding is not None:
        ledger_item={key:value for key,value in targets[0].items() if key not in {"status","evidence","next_action"}}
        ledger_digest=hashlib.sha256(json.dumps(ledger_item,sort_keys=True,separators=(",",":")).encode()).hexdigest()
        for _digest,attestation in attestations: attestation["local_ledger_digest"]=ledger_digest
    generated={state_domains.owner(STATE_DOMAIN,f"harness/attestations/{digest_value}.json"):(json.dumps(attestation,indent=2)+"\n").encode() for digest_value,attestation in attestations}
    generated[state_domains.owner(STATE_DOMAIN,"feature_list.json")]=ledger_payload
    if next_spec_directory is not None:
        pointer_content=next_spec_directory
        if STATE_DOMAIN=="harness" and pointer_content.startswith(".agent-harness/"):
            pointer_content=pointer_content[len(".agent-harness/"):]
        generated[state_domains.owner(STATE_DOMAIN,".specify/feature.json")]=(json.dumps({"feature_directory":pointer_content},indent=2)+"\n").encode()
    if deferred_payloads: return generated
    if local_binding is not None:
        blocked=_prepare_local_state_transition(session,generated,"complete-request")
        if blocked: print(blocked,file=sys.stderr); return 65
        _retire_completed_local_request()
        suffix=f" and activated {next_id}" if next_id else ""
        print(f"marked {item['id']} passing with immutable local evidence from {head}{suffix}"); return 0
    for path,payload in generated.items(): _publish_repository_file(ROOT/path,payload)
    suffix=f" and activated {next_id}" if next_id else ""
    print(f"marked {item['id']} passing with immutable evidence from {head}{suffix}"); return 0


def check_whitespace() -> int:
    names=git("ls-files","--cached","--others","--exclude-standard","-z").split(b"\0"); findings=[]
    for raw in names:
        if not raw: continue
        try: relative=raw.decode("utf-8"); path=ROOT/relative
        except UnicodeError: continue
        if not path.is_file() or path.is_symlink(): continue
        data=path.read_bytes()
        if b"\0" in data: continue
        try: text=data.decode("utf-8")
        except UnicodeError: continue
        for number,line in enumerate(text.splitlines(),1):
            if line.endswith((" ","\t")): findings.append(f"{relative}:{number}: trailing whitespace")
    if findings: print("\n".join(findings),file=sys.stderr); return 65
    print("tracked and untracked text whitespace is valid"); return 0


def check_artifacts() -> int:
    entries=git("status","--ignored","--porcelain=v1","-z","--untracked-files=all").split(b"\0"); findings=[]
    artifact_parts={"__pycache__",".pytest_cache",".mypy_cache",".ruff_cache","test-results","playwright-report",".DS_Store"}
    for raw in entries:
        if not raw.startswith(b"!! "): continue
        try: relative=raw[3:].decode("utf-8").rstrip("/")
        except UnicodeError: continue
        path=PurePosixPath(relative)
        if any(part in artifact_parts for part in path.parts) or path.suffix==".pyc" or path.name==".coverage": findings.append(relative)
    if findings:
        print("invocation artifacts must be removed before handoff:\n"+"\n".join(f"- {name}" for name in sorted(set(findings))),file=sys.stderr); return 65
    print("no ignored invocation artifacts remain"); return 0


def source_fingerprint() -> tuple[str,int]:
    raw=git("ls-files","-z","--cached","--others","--exclude-standard"); names=sorted({item.decode("utf-8") for item in raw.split(b"\0") if item})
    digest=hashlib.sha256(); count=0
    for relative in names:
        path=ROOT/relative
        try: metadata=path.lstat()
        except FileNotFoundError:
            digest.update(b"missing\0"+relative.encode("utf-8")+b"\0"); count+=1; continue
        if not stat.S_ISREG(metadata.st_mode): raise ValueError(f"source fingerprint requires regular files: {relative}")
        digest.update(b"file\0"+relative.encode("utf-8")+b"\0"+str(stat.S_IMODE(metadata.st_mode)).encode("ascii")+b"\0")
        with path.open("rb") as stream:
            while True:
                block=stream.read(1024*1024)
                if not block: break
                digest.update(block)
        digest.update(b"\0"); count+=1
    return digest.hexdigest(),count


def print_source_fingerprint() -> int:
    digest,count=source_fingerprint(); print(f"source-fingerprint sha256:{digest} files={count}"); return 0


def request_check(args: list[str]) -> int:
    if len(args)!=2 or args[0]!="--request" or not re.fullmatch(r"[A-Z][A-Z0-9]*-\d{3}",args[1]):
        print("Usage: bin/agent-session request-check --request REQUEST-ID",file=sys.stderr); return 64
    try:
        errors=validation_errors()+docs_errors()
        if errors: print("\n".join(errors),file=sys.stderr); return 65
        request,reference=read_bound_request(args[1])
        contract_errors=request_primitives.request_errors(request,request_facts(request))
        if contract_errors: print("\n".join(contract_errors),file=sys.stderr); return 65
        print(json.dumps({"schema":1,"request":reference["id"],"contract_digest":reference["contract_digest"],"valid":True},sort_keys=True)); return 0
    except ValueError as exc:
        print(str(exc),file=sys.stderr); return 65


def request_report(args: list[str]) -> int:
    if len(args)!=2 or args[0]!="--request": print("Usage: bin/agent-session request-report --request REQUEST-ID",file=sys.stderr); return 64
    try:
        request,reference=read_bound_request(args[1]); events=request["events"]
        current_entries={entry.get("id"):entry for entry in feature_document().get("features",[]) if isinstance(entry,dict)}
        open_gates=set()
        required=[]; optional=[]
        for identifier in request["contract"]["required"]:
            commits=[event["content_commit"] for event in events if event["kind"]=="content-commit" and event["phase"]=="required" and event["feature"]==identifier]
            current=current_entries.get(identifier,{})
            gates=current.get("external_gates",[]) if isinstance(current.get("external_gates",[]),list) else []
            open_gates.update(gates)
            required.append({"feature":identifier,"status":current.get("status"),"external_gates":gates,"content_commits":commits})
        for entry in request["contract"]["optional"]:
            identifier=entry["feature"]; commits=[event["content_commit"] for event in events if event["kind"]=="content-commit" and event["phase"]=="optional" and event["feature"]==identifier]
            deferred=next((event["reason"] for event in events if event["kind"]=="deferred" and event["feature"]==identifier),None)
            current=current_entries.get(identifier,{})
            gates=current.get("external_gates",[]) if isinstance(current.get("external_gates",[]),list) else []
            open_gates.update(gates)
            optional.append({"feature":identifier,"status":current.get("status"),"external_gates":gates,"content_commits":commits,"deferred_reason":deferred,"rationale":entry["rationale"],"removal_impact":entry["removal_impact"]})
        terminal=bool(events) and events[-1].get("kind")=="terminal" and events[-1].get("reason")=="REQUEST_COMPLETE"
        head=git("rev-parse","HEAD").decode().strip()
        print(json.dumps({"schema":1,"request":reference["id"],"contract_digest":reference["contract_digest"],"required":required,"optional":optional,"open_gates":sorted(open_gates),"events":events,"terminal":terminal,"head":head,"current_revalidated":False},sort_keys=True)); return 0
    except ValueError as exc: print(str(exc),file=sys.stderr); return 65


def next_action(args: list[str]) -> int:
    if args:
        print("Usage: bin/agent-session next-action",file=sys.stderr); return 64
    try:
        session=read_session()
        if session is None or session.get("request_ref") is None:
            print("durable request session required",file=sys.stderr); return 65
        result=request_decision(session)
        print(json.dumps(result,sort_keys=True)); return 0
    except ValueError as exc:
        print(str(exc),file=sys.stderr); return 65


def usage() -> int:
    print("Usage: script/harness.py [check|check-docs|check-whitespace|check-artifacts|source-fingerprint|generate-docs|init|verify-lane LANE|doctor|intent --prompt TEXT|record-outcome ...|measure KIND|metrics|request-check --request REQUEST-ID|next-action|route --binding-source local|trusted [--stage ROLE]|review-preflight|review-dispatch [--precommit --task Txxx]|start ... [--yolo]|adopt-candidate --confirm|revalidate --feature ID --confirm|pause [--reason TEXT]|resume --pause-id ID|archive|restore --pause-id ID|purge --confirm|remove --feature ID --confirm|recover-cleanup [--if-pending]|activate --feature ID|queue show|recover|reorder|suspend|unsuspend ...|review --task Txxx [--agent-id ID]|commit --task Txxx --message TEXT|advance|checkpoint --task Txxx|verify PROFILE...|finish [--check-only]|mark-passing [--activate-next FEATURE_ID]]",file=sys.stderr)
    return 64


def finish() -> int:
    try:
        with admin_transaction(): return _finish()
    except ValueError as exc:
        print(f"VERDICT: NOT_CLEAN\n{exc}",file=sys.stderr); return 65


def mark_passing(args: list[str]) -> int:
    if not args: next_id=None
    elif len(args)==2 and args[0]=="--activate-next" and re.fullmatch(r"[A-Z][A-Z0-9]*-\d{3}",args[1]): next_id=args[1]
    else: return usage()
    try:
        with admin_transaction(): return _mark_passing(next_id)
    except ValueError as exc:
        print(str(exc),file=sys.stderr); return 65


def main(argv: list[str]) -> int:
    try:
        if _BOOT_ERROR is not None: raise ValueError(_BOOT_ERROR)
        selected,argv=_state_domain_from_argv(argv)
        if selected is None:
            inherited=os.environ.get("AGENT_HARNESS_STATE_DOMAIN")
            if inherited not in {None,"application","harness"}: raise ValueError("AGENT_HARNESS_STATE_DOMAIN must be application or harness")
            selected=inherited or "application"
        recovery_only=(argv==["queue","recover"] or argv in (["recover-cleanup"],["recover-cleanup","--if-pending"]))
        _configure_state_domain(selected,allow_cleanup_recovery=bool(argv and argv[0] in {"purge","remove","recover-cleanup"}),allow_completed_recovery=recovery_only)
    except ValueError as exc:
        print(f"harness error: {exc}",file=sys.stderr); return 64
    if not argv: return usage()
    command,*args=argv
    try:
        if command=="check" and not args: return check_all()
        if command=="check-docs" and not args:
            errors=docs_errors();
            if errors: print("\n".join(errors),file=sys.stderr); return 65
            print("documentation is valid and current"); return 0
        if command=="check-whitespace" and not args: return check_whitespace()
        if command=="check-artifacts" and not args: return check_artifacts()
        if command=="source-fingerprint" and not args: return print_source_fingerprint()
        if command=="generate-docs" and not args: return generate_docs()
        if command=="init" and not args: return initialize()
        if command=="verify-lane" and len(args)==1: return verify_lane(args[0])
        if command=="doctor" and not args: return doctor()
        if command=="intent": return intent(args)
        if command=="policy": return policy_view(args)
        if command=="record-outcome": return record_outcome(args)
        if command=="measure": return measure(args)
        if command=="metrics" and not args: return metrics()
        if command=="trace" and not args: return trace()
        if command=="request-check": return request_check(args)
        if command=="request-report": return request_report(args)
        if command=="next-action": return next_action(args)
        if command=="route": return model_route(args)
        if command=="review-preflight": return review_preflight_command(args)
        if command=="review-dispatch": return review_dispatch_command(args)
        if command=="local-controller-record": return local_controller_record(args)
        if command=="controller-prepare": return controller_prepare(args)
        if command=="start": return start_session(args)
        if command=="adopt-candidate": return adopt_candidate(args)
        if command=="pause": return pause_work(args)
        if command=="resume": return resume_work(args)
        if command=="queue": return queue_command(args)
        if command=="archive": return archive_work(args)
        if command=="restore": return archive_work(args,restore=True)
        if command=="purge": return purge_features(args)
        if command=="remove": return remove_feature(args)
        if command=="recover-cleanup": return recover_cleanup_command(args)
        if command=="activate": return activate_work(args)
        if command=="revalidate": return revalidate_feature(args)
        if command=="review": return review(args)
        if command=="commit": return commit(args)
        if command=="advance": return advance(args)
        if command=="recover-commit": return recover_commit(args)
        if command=="checkpoint": return checkpoint(args)
        if command=="verify": return verify_profiles(args)
        if command=="finish" and (not args or args==["--check-only"]): return finish()
        if command=="mark-passing": return mark_passing(args)
        return usage()
    except (ValueError,KeyError,OSError,json.JSONDecodeError) as exc:
        print(f"harness error: {exc}",file=sys.stderr); return 70

if __name__=="__main__":
    raise SystemExit(main(sys.argv[1:]))
